import { createRoute, z } from '@hono/zod-openapi'

const AccessRuleConditionSchema = z
  .object({
    field: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The field to evaluate in the condition',
        example: 'created_by_user',
      }),
    operator: z
      .enum([
        'is',
        'is_not',
        'greater_than',
        'less_than',
        'greater_than_equal',
        'less_than_equal',
        'includes',
        'not_includes',
        'matches',
        'present',
      ])
      .exactOptional()
      .openapi({
        description: 'The comparison operator to use. Not all field types support all operators.',
        example: 'matches',
      }),
    value: z
      .xor([z.string(), z.int(), z.number(), z.boolean(), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "The value to compare against. Can be null for terminal operators like 'present' and 'not_present'",
        example: 'current_user',
      }),
  })
  .openapi({ required: [] })
  .openapi('AccessRuleCondition')

const AccessRuleSchema = z
  .object({
    conditions: z
      .object({
        all: z
          .array(AccessRuleConditionSchema)
          .exactOptional()
          .openapi({ description: 'All conditions must be true (AND logic)' }),
        any: z
          .array(AccessRuleConditionSchema)
          .exactOptional()
          .openapi({ description: 'Any condition can be true (OR logic)' }),
      })
      .exactOptional()
      .openapi({ description: 'The conditions that define when this rule applies', required: [] }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'When the access rule was created',
        example: '2025-09-17T10:15:30Z',
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description: 'A description of what this access rule does',
        example: 'Access rule that limits access to orders created by the current user',
      }),
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The access rule ID',
        example: 6862342718335,
      }),
    title: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The title of the access rule',
        example: 'Orders Created by Current User',
      }),
    updated_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'When the access rule was last updated',
        example: '2025-09-17T14:30:45Z',
      }),
  })
  .openapi({ required: [] })
  .openapi('AccessRule')

const AccessRuleCreateRequestSchema = z
  .object({
    access_rule: z
      .object({
        conditions: z
          .object({
            all: z
              .array(AccessRuleConditionSchema)
              .exactOptional()
              .openapi({ description: 'All conditions must be true (AND logic)' }),
            any: z
              .array(AccessRuleConditionSchema)
              .exactOptional()
              .openapi({ description: 'Any condition can be true (OR logic)' }),
          })
          .exactOptional()
          .openapi({
            description: 'The conditions that define when this rule applies',
            required: [],
          }),
        description: z
          .string()
          .exactOptional()
          .openapi({
            description: 'A description of what this access rule does',
            example: 'Access rule that limits access to orders created by the current user',
          }),
        title: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The title of the access rule',
            example: 'Orders Created by Current User',
          }),
      })
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ required: [] })
  .openapi('AccessRuleCreateRequest')

const AccessRuleFieldDefinitionSchema = z
  .object({
    group: z.string().exactOptional(),
    metadata: z
      .object({
        collection_key: z.string().exactOptional(),
        field_id: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .nullable()
          .exactOptional()
          .openapi({ type: ['integer', 'null'], format: 'int64' }),
        item_key: z.string().exactOptional(),
        source: z.string().nullable().exactOptional(),
        url: z.string().exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
    nullable: z.boolean().exactOptional(),
    operators: z
      .array(
        z
          .object({
            format: z.string().exactOptional(),
            terminal: z.boolean().exactOptional(),
            title: z.string().exactOptional(),
            value: z.string().exactOptional(),
          })
          .openapi({ required: [] }),
      )
      .exactOptional(),
    repeatable: z.boolean().exactOptional(),
    subject: z.string().exactOptional(),
    title: z.string().exactOptional(),
    type: z.string().exactOptional(),
    values: z
      .array(
        z
          .object({
            dynamic: z.boolean().exactOptional(),
            enabled: z.boolean().exactOptional(),
            title: z.string().exactOptional(),
            value: z.string().exactOptional(),
          })
          .openapi({ required: [] }),
      )
      .exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('AccessRuleFieldDefinition')

const AccessRuleDefinitionsResponseSchema = z
  .object({
    definitions: z
      .object({
        conditions_all: z
          .array(AccessRuleFieldDefinitionSchema)
          .exactOptional()
          .openapi({ description: "Available field definitions for 'all' conditions (AND logic)" }),
        conditions_any: z
          .array(AccessRuleFieldDefinitionSchema)
          .exactOptional()
          .openapi({ description: "Available field definitions for 'any' conditions (OR logic)" }),
      })
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ required: [] })
  .openapi('AccessRuleDefinitionsResponse')

const AccessRuleResponseSchema = z
  .object({ access_rule: AccessRuleSchema.exactOptional() })
  .openapi({ required: [] })
  .openapi('AccessRuleResponse')

