const AccountSettingsAgentsInputSchema = z
  .looseObject({
    agent_dashboard_enabled: z.boolean().exactOptional(),
    agent_home: z.boolean().exactOptional(),
    agent_workspace: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "May be silently dropped without effect in either direction\n(`validate_agent_workspace_update`, `settings_controller_support.rb`):\nturning it on is dropped unless the account is `agent_workspace_compatible?`\nand has `aw_self_serve_migration_enabled`, and (if Groups & Departments\naren't migrated) dropped outright when the account has a Chat product,\notherwise `groups.check_group_name_uniqueness` is forced to `true` as a side\neffect; turning it off is dropped if the account has native messaging or\n`aw_prevent_opt_out` without the auto-activation override. Setting it to\n`false` also forces `routing.enabled` to `false`\n(`settings_controller_support.rb:481-483`).\n",
      }),
    ai_async_comment_translations_eap_enabled: z.boolean().exactOptional(),
    ai_translation_disclosure_enabled: z.boolean().exactOptional(),
    dark_mode_agent_workspace: z.boolean().exactOptional(),
    dark_mode_terms_and_conditions_accepted: z.boolean().exactOptional(),
    explore_zra_monitoring_assistant_enabled: z.boolean().exactOptional(),
    focus_mode: z.boolean().exactOptional(),
    idle_timeout_enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Deprecated: silently dropped without effect for accounts with the\n`deprecate_idle_timeout_from_settings_api` Arturo\n(`has_deprecate_idle_timeout_from_settings_api?`,\n`settings_controller_support.rb`).\n',
      }),
    show_user_profile_page_toggle: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Silently dropped without effect unless the account has\n`has_ocp_customer_profile?` (`settings_controller_support.rb`).\n',
      }),
    spell_checker_enabled: z.boolean().exactOptional(),
    split_view_enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Writing this also writes the canonical EAP setting\n`split_view_eap_enabled` to the same value unless\n`split_view_eap_enabled` itself is explicitly set in the same request\n(`synchronize_split_view_eap_settings`,\n`settings_controller_support.rb`).\n',
      }),
    split_view_tos_accepted: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Writing this also writes the canonical EAP setting\n`split_view_eap_tos_accepted` to the same value unless\n`split_view_eap_tos_accepted` itself is explicitly set in the same request\n(`synchronize_split_view_eap_settings`,\n`settings_controller_support.rb`).\n',
      }),
    suggested_assignees_all_groups: z.boolean().exactOptional(),
    suggested_assignees_eap_enabled: z.boolean().exactOptional(),
    suggested_assignees_group_ids: z
      .array(z.int().min(1))
      .exactOptional()
      .openapi({
        description:
          'Each id must be a positive integer (`Parameters.gt(0)`). Duplicates are\nremoved before persistence (`settings_controller_support.rb`).\n',
      }),
    unified_agent_statuses: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'For accounts with `has_omnichannel_contact_centre_enabled?`, this is\noverwritten to match `routing.enabled` whenever `routing.enabled` is\npresent in the same request — even if this request does not otherwise\ntouch `agents` (`sync_routing_and_unified_agent_statuses`,\n`settings_controller_support.rb`).\n',
      }),
    unified_navigation_enabled: z.boolean().exactOptional(),
    unified_navigation_terms_and_conditions_accepted: z.boolean().exactOptional(),
  })
  .openapi({
    description:
      "Agent workspace/UI settings. See `settings_controller_support.rb`\n(`args_transformation_map['agents']`).\n\nA non-admin agent may update this category alone or alongside `tickets`, but\nonly when every key is one of `spell_checker_enabled`,\n`ai_async_comment_translations_eap_enabled` or\n`ai_translation_disclosure_enabled` — any other key in the same request falls\nback to requiring full admin (`tickets_settings_payload?`,\n`settings_controller.rb`).\n\n`additionalProperties: true`: the controller also dynamically permits two\nboolean keys per active, non-excluded EAP feature — `<feature>_tos_accepted`\nand `<feature>_enabled` for each `Zendesk::Eap::Catalog.writable_account_settings`\nentry (`eap_feature_parameters`/`writable_account_setting_binding`,\nmerged into both the outer gate and this category's write map). That set is not\nenumerable statically — it depends on which EAP features exist and are not\nexcluded at request time — so it is intentionally left open here rather than\nlisted.\n",
    required: [],
  })
  .openapi('AccountSettingsAgentsInput')

