const AccountSettingsMessagingInactivityInputSchema = z
  .object({
    enabled: z.boolean().exactOptional(),
    end_session: z.boolean().exactOptional(),
    reminders: z
      .array(
        z
          .object({
            message: z.string().min(1).max(2000),
            tags: z.array(z.string()).exactOptional(),
            ticket_status_id: z
              .int()
              .nullable()
              .exactOptional()
              .openapi({
                description:
                  "The only property in this entire payload where an explicit `null` is\ngenuinely accepted: the controller declares this parameter\nas `Parameters.integer | Parameters.nil` in the gate itself\n(`settings_controller.rb`), which is unaffected by the action's\n`forbid_nil_parameters` opt-in — that opt-in only disables the\nprocess-wide `allow_nil_for_everything` short-circuit, not an\nexplicit `| Parameters.nil` declared on this one field. Null (or\nomission) is accepted for reminders at index 0 or 1; a reminder at\nindex 2 that has a null or missing `ticket_status_id` fails\n`MessagingInactivityValidator`'s presence check with a 400.\n",
              }),
            timeout: z
              .int()
              .min(60)
              .max(900)
              .exactOptional()
              .openapi({
                description:
                  'Seconds (note: the top-level `timeout` sibling is minutes). Enforced\nat the parameter gate as `60..900`.\n',
              }),
          })
          .openapi({
            description:
              "See the positional requirements on the parent `reminders` array — which\nfields are required depends on this item's position in the array, not on\nthe item's own contents. `message` is the one exception: it is required\nat every position — the gate declares it `Parameters.string.required`,\nso a reminder without a `message` is rejected with a 400 before the\npositional validator runs.\n",
            required: ['message'],
          }),
      )
      .max(3)
      .exactOptional()
      .openapi({
        description:
          "At most 3 reminders. Tags on each reminder are lower-cased, split on commas\nand whitespace, deduplicated and compacted before validation\n(`sanitize_tags`, `settings_controller.rb`). Then validated positionally by\n`MessagingInactivityValidator` — the array's index, not any field on the\nitem, decides which fields are required: the first reminder (index 0) must\nomit both `timeout` and `ticket_status_id`; the second (index 1) must\nsupply `timeout`; the third (index 2) must supply both `timeout` and a\nnon-null `ticket_status_id`. A validation failure on any reminder renders a\n400 for the whole request.\n",
      }),
    ticket_status_id: z.int().exactOptional(),
    timeout: z
      .int()
      .min(3)
      .max(15)
      .exactOptional()
      .openapi({ description: 'Minutes. Enforced at the parameter gate as `3..15`.' }),
  })
  .openapi({
    description:
      "Messaging inactivity (capacity release) settings. See\n`settings_controller_support.rb` (`args_transformation_map['messaging_inactivity']`),\n`app/validators/messaging_inactivity_validator.rb`, and\n`settings_controller.rb#update`.\n",
    required: [],
  })
  .openapi('AccountSettingsMessagingInactivityInput')

