const AcknowledgedRiskObjectSchema = z
  .object({
    account_id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The id of the account the dismissal belongs to',
        readOnly: true,
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'The date and time the risk was acknowledged', readOnly: true }),
    dismissed_by_id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The id of the user who acknowledged the risk',
        readOnly: true,
      }),
    duration: AcknowledgedRiskDurationSchema,
    expires_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The date and time the dismissal lapses. Null when "duration" is "INDEFINITE"',
        readOnly: true,
      }),
    id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Automatically assigned ULID when the risk is acknowledged',
        readOnly: true,
      }),
    reason: z
      .string()
      .openapi({ description: 'Why the risk was accepted. Maximum length is 500 characters' }),
    setting_code: z
      .string()
      .openapi({ description: 'The code of the security setting whose risk was acknowledged' }),
    severity_at_dismissal: z
      .enum(['critical', 'recommended', 'healthy', 'unavailable', 'informational'])
      .openapi({
        description:
          'The severity of the risk at the time it was acknowledged, as assessed by the client',
      }),
    status: z
      .enum(['active', 'expired', 'withdrawn'])
      .exactOptional()
      .openapi({ description: 'The lifecycle state of the dismissal', readOnly: true }),
    updated_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'The date and time the acknowledged risk was last updated',
        readOnly: true,
      }),
    url: z
      .string()
      .exactOptional()
      .openapi({ description: 'The API url of this acknowledged risk', readOnly: true }),
  })
  .openapi({ required: ['setting_code', 'severity_at_dismissal', 'duration', 'reason'] })
  .openapi('AcknowledgedRiskObject')

