const DynamicContentItemVariantInputSchema = z
  .object({
    content: z
      .string()
      .openapi({
        description:
          "The content of the variant. Evaluated as Liquid in the `dc` namespace, so it must be valid Liquid and must not\nreference the item's own placeholder. Cannot be blank.\n",
      }),
    default: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Whether this variant is the item's default variant. Exactly one variant in the array must set it to `true`, and the\nrequest is rejected if none does. Only the literal `true` counts — `null` and any other value are treated as\n`false`. If more than one variant sets it to `true`, only the last of them is stored as the default and the earlier\nones are silently discarded.\n",
      }),
    locale_id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'The locale of the variant. Must be an existing locale id, and each locale may appear at most once per item.\n',
      }),
  })
  .openapi({
    description:
      'A variant supplied in the `variants` array of a Create Item request. Create Item accepts a narrower set of attributes\nthan the Item Variants API does, so this schema is not interchangeable with a standalone variant request body.\n',
    required: ['locale_id', 'content'],
  })
  .openapi('DynamicContentItemVariantInput')

const DynamicContentInputSchema = z
  .object({
    content: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The content of the item's default variant. Use this together with `default_locale_id` as a shorthand for creating\nan item with a single variant. Required when `variants` is omitted — without it the default variant has no content\nand the request is rejected. **Must not be sent together with `variants`** — the two forms are mutually\nexclusive, and sending both returns a 400 `Invalid attribute` error whatever the value is.\n",
      }),
    default_locale_id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description:
          'The default locale of the item, which becomes the locale of its default variant. Must be one of the locales the\naccount has active. Required unless `variants` is supplied, in which case this value is **ignored** and the default\nlocale is taken from the variant whose `default` is `true`. A `null` is therefore only accepted alongside\n`variants`; without `variants` it is rejected.\n',
      }),
    name: z
      .string()
      .openapi({
        description:
          "The unique name of the item. Must be unique within the account, must not contain non-ASCII characters and must not\nend in a hyphen. The item's `placeholder` is derived from it, and a name whose derived placeholder is already in\nuse is also rejected.\n",
      }),
    variants: z
      .array(DynamicContentItemVariantInputSchema)
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The variants to create for the item. Exactly one of them must have `default` set to `true`; if none does, the\nrequest is rejected because the item would have no default variant. Supplying this array makes `default_locale_id`\ninert, and `content` must not be sent alongside it. A `null` is treated as if the array were omitted, so the item is\ncreated from `default_locale_id` and `content` instead; an empty array is **not** equivalent and is rejected.\n',
      }),
  })
  .openapi({
    description:
      'A new dynamic content item. There are two ways to give it a default variant: supply `default_locale_id` and `content` to\ncreate a single variant, or supply the `variants` array. `content` must not be combined with `variants`;\n`default_locale_id` may be sent alongside `variants` but is ignored.\n',
    required: ['name'],
  })
  .openapi('DynamicContentInput')

