const EndUserIdentityCreateInputSchema = z
  .object({
    auto_ownership: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Write-only ownership control for the Shared Email EAP. When true, `owned` is attempted first and falls back to `shared` on an ownership conflict. The fallback is subject to the same restrictions as `ownership: shared`: it requires the `shared_email_creation_enabled` account setting, respects the per-brand shared-identity cap, and never applies to `google` identities - an ownership conflict for a Google-backed email identity is returned as an error instead of falling back. null is accepted and treated exactly like `false`. Only applies to `email` and `google` identities, and ignored unless the account has the Shared Email EAP enabled. Mutually exclusive with `ownership`; requests that supply both keys are rejected.',
      }),
    ownership: z
      .union([z.literal('owned'), z.literal('shared'), z.literal(null)])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Write-only ownership control for the Shared Email EAP. Only applies to `email` and `google` identities, and ignored unless the account has the Shared Email EAP enabled. null is accepted and falls back to `owned`. `shared` additionally requires the `shared_email_creation_enabled` account setting, is rejected outright for `google` identities (a Google-backed email identity can only be owned), and is subject to a per-brand cap on shared identities per address (100 by default; past the cap the request fails with `LimitExceeded`). A create that will send a verification email for a shared address is rate-limited and can be rejected with `429 Too Many Requests`. Mutually exclusive with `auto_ownership`; requests that supply both keys are rejected.',
      }),
    primary: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Makes the new identity the primary one. null is accepted and ignored. Only takes effect for `email` identities. For a verified\nemail identity (`verified: true` or `verification_method: low`) the identity becomes primary\nimmediately; for an unverified one the promotion is deferred - the verification email link carries\n`make_primary=true`, so the identity becomes primary (and the former primary is removed) when the\nrecipient verifies. Ignored for non-email identity types, including `google`.\n\nTo promote an identity that already exists, use the\n[Make Identity Primary](#make-identity-primary) endpoint instead.\n',
      }),
    type: z
      .enum([
        'email',
        'twitter',
        'facebook',
        'google',
        'agent_forwarding',
        'phone_number',
        'messaging',
        'slack',
      ])
      .exactOptional()
      .openapi({
        description:
          'The type of identity to create.\n\nOnly the types listed here can be created through this endpoint. The remaining identity types\n(`any_channel`, `foreign`, `sdk`, `microsoft`) are created by internal systems only, and a request\nfor one of them is rejected with a `400`.\n\n`messaging` and `slack` back internal channel integrations. `slack` additionally requires the\nSlack identity feature to be enabled on the account.\n',
      }),
    value: z
      .string()
      .max(255)
      .exactOptional()
      .openapi({
        description:
          'The identifier for this identity. An email address for `email` and `google`, the screen name for\n`twitter`, the Facebook user id for `facebook`, and an E.164 phone number for `phone_number` and\n`agent_forwarding`. Phone numbers are validated unless the account has phone number validation\nturned off.\n',
      }),
    verification_method: z
      .union([z.literal('none'), z.literal('low'), z.literal(null)])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The verification state to create the identity with. `low` creates a verified identity and\nsuppresses the verification email. Only `none` and `low` are accepted here; the higher methods\n(`sso`, `embed`, `full`) are set by the corresponding authentication flows.\n\nHas no effect for `phone_number` and `agent_forwarding` identities, which are always verified, nor\nfor `slack`. Also ignored when creating an email identity (including `google`) for the account owner: that identity is\nalways created unverified and a verification email is sent.\n\nnull is accepted and treated exactly like `none`. Because this property wins over `verified`,\nsending `verified: true` alongside `verification_method: null` creates an unverified identity.\n',
      }),
    verified: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Creates the identity already verified, equivalent to `verification_method: low`. Deprecated - use\n`verification_method` instead. Ignored when `verification_method` is also sent - that property\nwins. null is accepted and treated exactly like `false`.\n\nHas no effect for `phone_number` and `agent_forwarding` identities, which are always verified, nor\nfor `slack`. Also ignored when creating an email identity (including `google`) for the account owner: that identity is\nalways created unverified and a verification email is sent.\n',
        deprecated: true,
      }),
  })
  .openapi({ required: [] })
  .refine(
    (val) =>
      !z
        .unknown()
        .superRefine((val, ctx) => {
          if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
            if (!Object.hasOwn(val, 'ownership')) {
              ctx.addIssue({ code: 'custom' })
            }
            if (!Object.hasOwn(val, 'auto_ownership')) {
              ctx.addIssue({ code: 'custom' })
            }
          }
        })
        .openapi({ required: ['ownership', 'auto_ownership'] })
        .safeParse(val).success,
  )
  .openapi({ required: ['type', 'value'] })
  .openapi('EndUserIdentityCreateInput')

