const GroupSLAPolicyMetricInputSchema = z
  .union([
    z.looseObject({}).openapi({ required: ['target'] }),
    z.looseObject({}).openapi({ required: ['target_in_seconds'] }),
  ])
  .and(
    z
      .object({
        business_hours: z
          .boolean()
          .openapi({
            description:
              'Whether the target is measured in business hours rather than calendar hours. Required — the value is assigned unconditionally and then validated for inclusion in `true`/`false`, so omitting it fails validation',
            example: true,
          }),
        metric: z
          .literal('group_ownership_time')
          .openapi({
            description:
              'The time being measured. `group_ownership_time` is the only metric supported by group SLA policies — the account-level SLA metrics are not accepted here',
            example: 'group_ownership_time',
          }),
        priority: z
          .string()
          .openapi({
            description:
              'The ticket priority the target applies to. Allowed values are `low`, `normal`, `high`, or `urgent`',
            example: 'normal',
          }),
        target: z
          .int()
          .min(1)
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The target for the metric, in minutes. Ignored when `target_in_seconds` is supplied. Either `target` or `target_in_seconds` must be given. The allowed-range limits described on `target_in_seconds` apply here too, since seconds are derived from minutes. A null value is accepted only when `target_in_seconds` is supplied, because it is then not assigned at all; a null with neither target given fails the numericality validation',
            example: 1800,
          }),
        target_in_seconds: z
          .int()
          .min(1)
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The target for the metric, in seconds. Takes precedence over `target`. On accounts with the SLA metrics allowed range feature, values below 15 seconds and above 31536000 seconds (8760 hours) are rejected. A null value is ignored, so the target falls back to `target`',
            example: 108000,
          }),
      })
      .openapi({ required: ['priority', 'metric', 'business_hours'] }),
  )
  .openapi({
    description:
      'A target for one combination of ticket priority and metric. Each priority and metric pair may only appear once in a policy',
    required: ['priority', 'metric', 'business_hours'],
  })
  .openapi('GroupSLAPolicyMetricInput')

