const SLAPolicyUpdateInputSchema = z
  .object({
    description: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The description of the SLA policy. A blank or `null` value is ignored, so the description cannot be cleared through this endpoint',
        example: 'For urgent incidents, we will resolve the ticket within 2 hours',
      }),
    filter: z
      .union([SLAPolicyFilterInputSchema, z.object({}).nullable()])
      .exactOptional()
      .openapi({
        description:
          "The conditions a ticket must match for the SLA policy to be applied to it. A supplied filter **replaces the policy's conditions in full**, so omitting `all` or sending it as `null` or `[]` removes the policy's existing `all` conditions - and likewise for `any`. Sending `null` or `{}` for `filter` itself is a no-op that leaves the current filter in place",
      }),
    metric_settings: z
      .union([SLAPolicyMetricSettingsInputSchema, z.object({}).nullable()])
      .exactOptional()
      .openapi({
        description:
          'Per-metric activation and fulfillment settings. `null` is ignored and leaves the current settings in place, whereas `{}` **clears every setting** on the policy',
      }),
    policy_metrics: z
      .array(SLAPolicyMetricInputSchema)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The targets for the policy. See [Policy Metric](#policy-metric). Supplying this replaces the policy's targets in full, so a partial list deletes the targets it omits. `null` and `[]` are both ignored and leave the current targets in place",
      }),
    policy_triggers: z
      .array(SLAPolicyTriggerInputSchema)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Notifications attached to the policy. Only acted on when the account has the SLA policy triggers feature; without it the field is accepted and then silently dropped. When it is acted on, the supplied list replaces the policy's notifications in full. `null` and `[]` are both ignored and leave the current notifications in place",
      }),
    position: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Position of the SLA policy, which determines the order policies are matched in. A `null` value is ignored and the current position is kept',
        example: 3,
      }),
    title: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The title of the SLA policy. A blank or `null` value is ignored and the current title is kept',
        example: 'Urgent Incidents',
      }),
  })
  .openapi({
    description:
      "Only the supplied properties are updated. Supplying `policy_metrics` replaces the policy's targets in full. Every property here is also a no-op when sent as null, so no property can be cleared that way",
    required: [],
  })
  .openapi('SLAPolicyUpdateInput')

const SLAPolicyUpdateRequestSchema = z
  .object({ sla_policy: SLAPolicyUpdateInputSchema })
  .openapi({ required: ['sla_policy'] })
  .openapi('SLAPolicyUpdateRequest')

