const SatisfactionRatingInputSchema = z
  .object({
    comment: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The comment left by the requester with this rating. Omitting the property, sending an empty string and sending `null` are equivalent — the rating is created with no comment. A non-empty comment upgrades the score stored on the ticket from "good" to "good_with_comment" or from "bad" to "bad_with_comment", although the `score` in the response still reads "good" or "bad"',
      }),
    reason_code: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description:
          'The reason code for a negative rating. See [Reason codes](/api-reference/ticketing/ticket-management/satisfaction_reasons/#reason-codes) in the Satisfaction Reasons API. **This property is only accepted on accounts that have satisfaction reasons enabled**; on any other account the property is silently dropped and the rating is created without it, with a success response and no error. It also only takes effect on a "bad" score — a "good" score resets the reason to the default 0 ("no reason"). An explicit `null` is accepted and ignored, preserving any reason code already recorded on the ticket',
      }),
    score: z
      .enum(['good', 'bad'])
      .openapi({
        description:
          'The rating. Only "good" and "bad" create a rating: the parameter filter accepts the full satisfaction-score vocabulary used by the List Satisfaction Ratings `score` filter ("offered", "unoffered", "received", "good_with_comment" and so on), but any value other than "good" or "bad" is mapped to no score and the request then fails validation with a 422 rather than a 400',
      }),
  })
  .openapi({ required: ['score'] })
  .openapi('SatisfactionRatingInput')

