const SharingAgreementUpdateInputSchema = z
  .object({
    status: z
      .union([
        z.literal('pending'),
        z.literal('accepted'),
        z.literal('declined'),
        z.literal('inactive'),
        z.literal('failed'),
        z.literal('ssl_error'),
        z.literal('configuration_error'),
        z.literal(''),
        z.literal(null),
      ])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The state of the agreement. Use `accepted` to accept an invitation you have received, `declined`\nto reject or cancel one, `inactive` to suspend an accepted agreement without deleting it, and\n`accepted` again to resume a suspended one. A request that actually changes the status sends the\nnew state to the account on the other side of the agreement, unless the new status is\n`ssl_error`; a request that leaves the status as it was sends nothing. Moving to `inactive`,\n`failed`, `ssl_error` or `configuration_error` also emails every administrator on your account;\nthe other statuses do not.\n\nThree transitions are rejected. Moving back to `accepted` is rejected unless Zendesk recorded\nyour own account as the one that suspended the agreement, which it does only for an `accepted`\nto `inactive` change made on your side — so an agreement the *other* account suspended cannot be\nresumed from here. Moving to `pending` or `accepted` is rejected while you hold another accepted\nagreement with the same remote URL in the same direction. Moving to anything other than\n`inactive` or `declined` is rejected when the agreement\'s remote URL has come to point back at\nyour own account, which can happen after a subdomain change.\n\n`failed`, `ssl_error` and `configuration_error` describe communication problems and are normally\nset by Zendesk rather than by a client, but they are accepted here.\n\nNote that `declined` set through this endpoint marks the agreement declined without deleting it\nor its shared tickets — use the delete endpoint for that.\n\nA blank value is accepted and leaves the status unchanged. `null` and an empty string are both\nlisted in the enum for that reason; a whitespace-only string such as `" "` behaves the same way\nbut cannot be enumerated. Omitting the property has the same effect. An unrecognized status name\nis rejected.\n',
      }),
  })
  .openapi({
    description:
      'The writable attributes accepted when updating a sharing agreement. Only `status` can be changed;\nthe sharing options chosen when the agreement was created are fixed for its lifetime. Sending an\nempty object is accepted and changes nothing, though the agreement is re-validated on every request,\nso the rejections described under `status` can apply even to a request that changes nothing.\n',
    required: [],
  })
  .openapi('SharingAgreementUpdateInput')

const SharingAgreementUpdateRequestSchema = z
  .object({ sharing_agreement: SharingAgreementUpdateInputSchema })
  .openapi({ required: ['sharing_agreement'] })
