const TagsAddRequestSchema = z
  .object({
    safe_update: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Write only. When `true`, protects against ticket update collisions. Requires\n`updated_stamp`; sending `safe_update` without it returns a `409` on every resource.\n`false` has the same effect as omitting the property or sending `null`: no collision\ncheck is performed. Only affects the outcome for tickets. See [Protecting against\nticket update collisions](/api-reference/ticketing/tickets/tickets/#protecting-against-ticket-update-collisions)\n',
        writeOnly: true,
      }),
    tags: z
      .xor([z.array(z.string()).nullable(), z.string()])
      .exactOptional()
      .openapi({
        description:
          'The tags to add to the ones already applied. An array of tag strings, or a single\nstring. In either form each value is split on whitespace and on `,` `;` `|` `(` `)`,\nthen stripped of special characters, downcased and de-duplicated. `null`, an empty array,\nan empty string and omitting the property are all accepted and leave the existing tags\nunchanged. Unlike the Set Tags operation, nothing here can clear a tag\n',
        example: ['customer'],
      }),
    updated_stamp: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Write only. The resource's last known `updated_at`. The update is applied only if it\nstill matches, otherwise the request returns a `409`. `null` has the same effect as\nomitting the property: it is ignored unless `safe_update` is set, in which case the\nrequest returns a `409`. Only affects the outcome for tickets. See the `safe_update`\nproperty\n",
        writeOnly: true,
      }),
    via: z
      .object({
        author_zrn: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'Write only. The Zendesk Resource Name (ZRN) of the actor on whose behalf the\nupdate is made, recorded on the audit. At most 100 characters and must be a\nvalid ZRN. Only affects the outcome for tickets\n',
            writeOnly: true,
          }),
        channel: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The channel to attribute the update to. Defaults to `web_service` when unset,\n`null` or unrecognized\n',
          }),
      })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Write only. `null` is accepted and treated as omitted. Only affects the outcome for tickets',
        writeOnly: true,
        required: [],
      }),
  })
  .openapi({ required: [] })
  .openapi('TagsAddRequest')

