      id: 7,
      key: 'custom_field_1',
      position: 9999,
      raw_description: '{{dc.my_description}}',
      raw_title: 'Custom Field 1',
      regexp_for_validation: null,
      title: 'Custom Field 1',
      type: 'text',
      updated_at: '2012-10-16T16:04:06Z',
      url: 'https://company.zendesk.com/api/v2/user_fields/7',
