const UserFieldOptionCreateOrUpdateInputSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description:
          "The id of an existing, active option to update. A deleted option's id is not accepted and returns 404; a deleted\noption can only be restored through the `value` match below. Omit `id` or send null to create a new option, or to\nmatch an existing one by `value`.\n",
      }),
    name: z.string().openapi({ description: 'The presentation name of the option' }),
    position: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "The relative position of the option in the field's option list. Defaults to the end of the list when creating a new option",
      }),
    value: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The tag value applied to the user when the option is selected. Must be unique across the account's field options.\nRequired when creating an option; when updating an existing option by `id`, omitting it leaves the current value\nunchanged.\n",
      }),
  })
  .openapi({
    description:
      'A single option for a `dropdown` user field, created or updated in place. Fields created with `type: tagger` are\ndropdown fields and are also supported. `multiselect` fields are not: this endpoint returns 404 for them, and their\noptions must be managed through the `custom_field_options` array on Update User Field.\n\nSupplying `id` updates that option. When `id` is omitted or null, the API looks up an option on the field with the\nsame `value`, whether that option is active or previously deleted. If one is found it is updated in place, restored if\nit had been deleted, and the response is a 200 rather than a 201 — so reusing an existing `value` silently mutates\nthat option instead of creating a new one. Otherwise a new option is created.\n',
    required: ['name'],
  })
  .openapi('UserFieldOptionCreateOrUpdateInput')

const UserFieldOptionRequestSchema = z
  .object({ custom_field_option: UserFieldOptionCreateOrUpdateInputSchema })
  .openapi({ required: ['custom_field_option'] })
  .openapi('UserFieldOptionRequest')

const UserFieldOptionUpdateInputSchema = z
  .object({
    id: z
      .xor([
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({ type: 'integer', format: 'int64' }),
        z.string().nullable(),
      ])
      .openapi({
        description:
          'The id of an existing option to update in place. To add a new option, send null or an empty string. The key\nitself is mandatory on every entry: an option with no `id` key is rejected with a `BlankValue` error.\n',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The presentation name of the option. Must not be blank. Required when adding a new option',
      }),
    raw_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The dynamic content placeholder for the option's name. See [Dynamic Content](/api-reference/ticketing/ticket-management/dynamic_content/).\nWhen supplied, this value is written to `name` and any `name` sent alongside it is discarded. Sending null is\naccepted and discarded: `name` is left as sent.\n",
      }),
    value: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The tag value applied to the user when the option is selected. Must be unique across the account's field options.\nRequired when adding a new option; when updating an existing option by `id`, omitting it leaves the current value\nunchanged.\n\nWhen adding an option whose `value` matches one that was previously deleted, the deleted option is restored\ninstead. That match is case-sensitive, so a value differing only in case does not restore the old option.\n",
      }),
  })
  .openapi({
    description:
      'An option for a `dropdown`, `tagger`, or `multiselect` custom user field, as supplied when updating the field. The\n`id` key must always be present.\n',
    required: ['id'],
  })
  .openapi('UserFieldOptionUpdateInput')

