const UserLoginParamsSchema = z
  .preprocess(
    (val) => {
      if (typeof val !== 'string') return val
      const parts = val.split(',')
      const entries: [string, string][] = []
      for (const part of parts) {
        const at = part.indexOf('=')
        const last = entries.at(-1)
        if (at >= 0) {
          entries.push([part.slice(0, at), part.slice(at + 1)])
        } else if (last === undefined) {
          return val
        } else {
          last[1] += ',' + part
        }
      }
      return Object.fromEntries(entries)
    },
    z.object({ email: z.string().exactOptional(), password: z.string().exactOptional() }),
  )
  .openapi({
    param: {
      name: 'user',
      in: 'path',
      description: 'Provides user email and password for password login\n',
      style: 'deepObject',
      explode: true,
      required: true,
      schema: {
        type: 'object',
        properties: { email: { type: 'string' }, password: { type: 'string' } },
      },
      example: { email: 'test@zd-dev.com', password: '123456' },
    },
    required: [],
  })

