export const getApiV2TargetTypeTargetIdRelationshipFieldsFieldIdSourceTypeRoute = createRoute({
  method: 'get',
  path: '/api/v2/{target_type}/{target_id}/relationship_fields/{field_id}/{source_type}',
  tags: ['Lookup Relationships'],
  summary: 'Get sources by target',
  description:
    'Returns a list of source objects whose values are populated with the id of a related target object.  For example,\nif you have a lookup field called "Success Manager" on a ticket, this endpoint can answer the question,\n"What tickets (sources) is this user (found by `target_type` and `target_id`)\nassigned as the \'Success Manager\' (field referenced by `field_id`)?"\n\nThis endpoint also resolves [multi-lookup fields](/api-reference/ticketing/lookup_relationships/lookup_relationships/#about-multi-lookup-relationship-fields).\nPass the multi-lookup field\'s id as `field_id` and "zen:ticket" as `source_type` to list the tickets that\nreference a target record through the field. Multi-lookup reverse lookups are resolved through search, so tickets\nthe requesting agent can\'t view are excluded.\n\n#### Allowed For\n\n* Agents\n\n#### Pagination\n\n* Cursor pagination (recommended)\n* Offset pagination\n\nFor a multi-lookup `field_id`, only cursor pagination applies. Offset pagination parameters are ignored and the\nresponse uses cursor pagination.\n\nSee [Pagination](/api-reference/introduction/pagination/).\n',
  operationId: 'GetSourcesByTarget',
  request: {
    params: z.object({
      target_type: z
        .string()
        .openapi({
          param: {
            name: 'target_type',
            in: 'path',
            description:
              'The type of object the relationship field is targeting.\nThe options are "zen:user", "zen:ticket", "zen:organization", and "zen:custom_object:CUSTOM_OBJECT_KEY"\n',
            required: true,
            schema: { type: 'string' },
            example: 'zen:custom_object:apartment',
          },
        }),
      target_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'target_id',
            in: 'path',
            description: 'The id of the object the relationship field is targeting\n',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            example: 1234,
          },
        }),
      field_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'field_id',
            in: 'path',
            description: 'The id of the lookup relationship field\n',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            example: 1234,
          },
        }),
      source_type: z
        .string()
        .openapi({
          param: {
            name: 'source_type',
            in: 'path',
            description:
              'The type of object the relationship field belongs to (example. ticket field belongs to a ticket object).\nThe options are "zen:user", "zen:ticket", "zen:organization", and "zen:custom_object:CUSTOM_OBJECT_KEY"\n',
            required: true,
            schema: { type: 'string' },
            example: 'zen:custom_object:apartment',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: ReverseLookupResponseSchema,
          examples: { default: ReverseLookupUsersResponseExampleExample },
        },
      },
    },
  },
})

