export const postApiV2AccountsRoute = createRoute({
  method: 'post',
  path: '/api/v2/accounts',
  tags: ['Reseller'],
  summary: 'Create Trial Account',
  operationId: 'CreateTrialAccount',
  request: {
    body: {
      content: {
        'application/json': {
          schema: TrialAccountRequestSchema,
          examples: { default: TrialAccountRequestExampleExample },
        },
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              account: z
                .object({
                  _zd_choose_shard_udupi: z
                    .preprocess(
                      (val) => (val === 'null' ? null : val),
                      z
                        .preprocess(
                          (val) =>
                            typeof val === 'string' &&
                            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                              ? Number(val)
                              : val,
                          z.int(),
                        )
                        .nullable(),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'Preferred database shard for the new account. Formerly read by `Zendesk::Accounts::Initializer` on the Classic creation path, which PLATOPS-1372 removed; the value is now accepted and forwarded verbatim, and whether the account service honours it is outside this repository.',
                    }),
                  currency: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Currency code for the account.' }),
                  employee_service_suite_trial: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      z.preprocess(
                        ((read) => (val: unknown) => {
                          const result = read.safeParse(val)
                          return result.success ? result.data : val
                        })(z.stringbool()),
                        schema,
                      ),
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.xor([z.boolean().nullable(), z.string(), z.int()]))
                    .exactOptional()
                    .openapi({
                      description:
                        'Provisions an Employee Service Suite trial (a professional-plan `employee_service_suite` SKU expiring in 14 days) with `account.account_type` set to `pre_spp`. Enabled by any value the parameter gate coerces to true (`1`, `"1"`, `true`, `"true"`, `"on"`). Takes effect only when `zendesk_suite_trial` is not set, which is evaluated first.',
                    }),
                  google_apps_domain: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Google Workspace domain to associate with the account. Must not already be routed to another account and must not be `gmail.com`; either returns `409 Conflict`.',
                    }),
                  help_desk_size: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        "Free-form description of the expected number of agents, for example `Small Team`, `1-9` or `Large group`. Surfaced verbatim as `company_size` in the signup tracking properties (`Account::Tracking`); any categorisation happens downstream of this repository. Not enforced by this controller's own gates; `Account` validates its presence on create, but the record is created by the account service, out of process. `null` and omission are indistinguishable here.",
                    }),
                  language: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Locale for the new account, for example `ja`. Copied to `account.locale` before the payload is forwarded.',
                    }),
                  multiproduct: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      z.preprocess(
                        ((read) => (val: unknown) => {
                          const result = read.safeParse(val)
                          return result.success ? result.data : val
                        })(z.stringbool()),
                        schema,
                      ),
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.xor([z.boolean().nullable(), z.string(), z.int()]))
                    .exactOptional()
                    .openapi({
                      description:
                        "Legacy switch for the account's product configuration. PLATOPS-1372 removed the multiproduct branch and the legacy Classic fallback from `create`, so this controller no longer reads the value and it has no effect on which service handles the request. It is still accepted by the parameter gate and forwarded verbatim to the account service like every other permitted property; whether it affects provisioning is decided by the account service, outside this repository. The value the account service returns is echoed back as `account.multiproduct` in the response body.",
                    }),
                  name: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        "The name of the account. Not enforced by this controller's own gates; accepted and forwarded to the account service, which decides whether it is required. `null` and omission are indistinguishable here.",
                    }),
                  remote_authentication: z
                    .union([TrialAccountRemoteAuthenticationInputSchema, z.object({}).nullable()])
                    .exactOptional()
                    .openapi({
                      description:
                        'Single sign-on configuration for the new account. Accepted and forwarded to the account service verbatim; this controller does not read it.',
                    }),
                  remote_login_url: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Remote login URL for the account. Distinct from `remote_authentication.remote_login_url`; both are accepted and forwarded.',
                    }),
                  source: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Provisioning channel this signup came from. Also copied into `trial_extras.source` when present.',
                    }),
                  subdomain: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        'The subdomain to provision, and the only place this controller looks for it. Must match `^[a-z0-9][a-z0-9-]{1,}[a-z0-9]$` (`SUBDOMAIN_PATTERN`, lib/vars.rb), must not start with `xn--`, and must be neither taken nor reserved; the value is trimmed of surrounding whitespace before those checks run. A missing, blank, invalid, reserved or taken subdomain returns `409 Conflict` with a `success: false` body rather than a validation error. Note that a successful request locks the subdomain in the shared cache for 60 seconds *before* the account is created, so retrying a request that failed with a `422` returns a `409` until the lock expires.',
                    }),
                  suite_trial: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      z.preprocess(
                        ((read) => (val: unknown) => {
                          const result = read.safeParse(val)
                          return result.success ? result.data : val
                        })(z.stringbool()),
                        schema,
                      ),
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.xor([z.boolean().nullable(), z.string(), z.int()]))
                    .exactOptional()
                    .openapi({
                      description:
                        'Provisions a `suite` trial SKU instead of the default `support` SKU. Also copied into `trial_extras.suite_trial` when present. Declared as a boolean in the parameter gate, which also accepts and coerces the string and integer spellings `"true"`, `"1"`, `"on"`, `1`, `"false"`, `"0"` and `0`.',
                    }),
                  utc_offset: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.xor([z.int().nullable(), z.string()]))
                    .exactOptional()
                    .openapi({
                      description:
                        'Time zone for the new account, given either as a UTC offset (for example `7` or `"7"`) or as an ActiveSupport time zone name. Resolved by `Account::Localization.utc_to_tz` into `account.time_zone`; an unrecognised, empty or `null` value falls back to `Eastern Time (US & Canada)`.',
                    }),
                  zendesk_suite_trial: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      z.preprocess(
                        ((read) => (val: unknown) => {
                          const result = read.safeParse(val)
                          return result.success ? result.data : val
                        })(z.stringbool()),
                        schema,
                      ),
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.xor([z.boolean().nullable(), z.string(), z.int()]))
                    .exactOptional()
                    .openapi({
                      description:
                        'Provisions a Zendesk Suite trial (a professional-plan `zendesk_suite` SKU expiring in 14 days) rather than the default SKU. Enabled by any value the parameter gate coerces to true (`1`, `"1"`, `true`, `"true"`, `"on"`); every other value is ignored. Evaluated before `employee_service_suite_trial`.',
                    }),
                })
                .openapi({
                  description:
                    'Attributes of the trial account to provision. Corresponds to `Api::V2::AccountsController::ACCOUNT_PARAMETER`.',
                  required: ['subdomain'],
                })
                .openapi({ description: 'Attributes of the account to provision.' }),
              address: z
                .object({
                  city: z.string().nullable().exactOptional().openapi({ description: 'City.' }),
                  phone: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      schema,
                    ]))(z.xor([z.string().min(1), z.int()])).openapi({
                    description:
                      'Contact phone number. A missing or blank value returns `422 Unprocessable Entity` with "Address phone can\'t be blank" (`Zendesk::Accounts::CreationParamsValidator`). No format is enforced.',
                  }),
                  province: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'State, province or region.' }),
                  street: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Street address.' }),
                  zip: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Postal code.' }),
                })
                .openapi({
                  description:
                    'Contact address for the trial account. Corresponds to `Api::V2::AccountsController::ADDRESS_PARAMETER`.',
                  required: ['phone'],
                })
                .openapi({
                  description: 'Contact address of the account. Only `phone` is required.',
                }),
              agents: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(TrialAccountAgentInputSchema),
                )
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Additional agents to invite into the new account. Forwarded to the account creator; this controller does not read the value.',
                }),
              force_pod_id: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Pins the new account to a specific pod. When present it is forwarded as `pod_id` to the account creator.',
                }),
              owner: z
                .object({
                  email: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        "The owner's email address. A malformed address returns `422 Unprocessable Entity` (`Zendesk::Accounts::CreationParamsValidator#valid_owner_email`).",
                    }),
                  is_verified: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      z.preprocess(
                        ((read) => (val: unknown) => {
                          const result = read.safeParse(val)
                          return result.success ? result.data : val
                        })(z.stringbool()),
                        schema,
                      ),
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.xor([z.string().nullable(), z.boolean(), z.int()]))
                    .exactOptional()
                    .openapi({
                      description:
                        "Marks the owner's email as already verified. Only the values `1` and `true` (in their string, boolean or integer spellings) count as verified; the controller normalises whatever is supplied to a boolean before forwarding it, so any other value, `null`, and omitting the property, mean unverified.",
                    }),
                  name: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        'The owner\'s full name. A missing or blank value returns `422 Unprocessable Entity` with "Owner name can\'t be blank" (`Zendesk::Accounts::CreationParamsValidator`).',
                    }),
                  password: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Initial password for the owner. When omitted the owner is created without one and is expected to set it through the owner verification link returned in the response.',
                    }),
                })
                .openapi({
                  description:
                    'Attributes of the owner to create alongside the trial account. Corresponds to `Api::V2::AccountsController::OWNER_PARAMETER`.',
                  required: ['name', 'email'],
                })
                .openapi({ description: 'Attributes of the account owner to create.' }),
              partner: z
                .union([TrialAccountPartnerInputSchema, z.object({}).nullable()])
                .exactOptional()
                .openapi({
                  description:
                    'Reseller/partner attribution for the account. Accepted and forwarded to the account service verbatim; this controller does not read it. The `partner_name`/`partner_url` account settings these historically became were written on the Classic creation path, removed by PLATOPS-1372.',
                }),
              trial_extras: z
                .looseObject({})
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Free-form bag of trial metadata. Every value is coerced to a string, and the controller then injects `confirm_origin`, `creation_channel`, `original_remote_ip`, `region`, and copies `account.source` and `account.suite_trial` into it (`AccountsController#account_creation_params_trial_extras`). Declared as `Parameters.anything`, so a non-object value passes the parameter gate but then fails when the controller iterates it.',
                }),
            })
            .openapi({
              description:
                'Payload for provisioning a trial account through the reseller API. This controller does not filter the payload down before use: after the parameter gate it forwards the whole request body verbatim to the account creator, adding `skus`, `pod_id` and the derived `account.time_zone`, `account.locale`, `account.account_type` and `owner.is_verified`. Every request goes to `api/services/accounts` on the account service, with the SKU chosen by `account.zendesk_suite_trial` and `account.employee_service_suite_trial`; the multiproduct branch and the legacy Classic fallback that PLATOPS-1372 removed were the only alternatives. All requests merge a `trial_extras` bag into the payload. Unknown keys are stripped before the request is forwarded.',
              required: ['account', 'owner', 'address'],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created response',
      content: {
        'application/json': {
          schema: TrialAccountResponseSchema,
          examples: { default: TrialAccountResponseExampleExample },
        },
      },
    },
  },
})

