export const postApiV2ApprovalClarificationFlowMessagesRoute = createRoute({
  method: 'post',
  path: '/api/v2/approval_clarification_flow_messages',
  tags: ['Approval Requests'],
  summary: 'Create Approval Clarification Flow Message',
  description:
    "Adds a message to the clarification flow thread for an approval request and returns the\nfull, updated thread.\n\n#### Allowed For\n\n* The approval request's assignee or creator, the ticket assignee, or a member of the\n  assigned group\n* Any user who can view the ticket when the `approvals_allow_comments_from_ticket_viewers`\n  feature is enabled\n",
  operationId: 'CreateApprovalClarificationFlowMessage',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              approval_request_id: z
                .string()
                .openapi({
                  description: 'The id of the approval request to add the message to',
                  example: '01ARZ3NDEKTSV4RRFFQ69G5FAV',
                }),
              message: z
                .string()
                .openapi({
                  description: 'The content of the message',
                  example: 'Can you clarify the budget line?',
                }),
              raw: z
                .any()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Slack rich-text blocks for the message. Only used when `via` is `SLACK`',
                }),
              via: z
                .enum(['SUPPORT', 'SLACK', ''])
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The channel the message is sent through. Defaults to `SUPPORT` when omitted or blank',
                }),
            })
            .openapi({ required: ['approval_request_id', 'message'] }),
          examples: {
            default: {
              value: {
                approval_request_id: '01ARZ3NDEKTSV4RRFFQ69G5FAV',
                message: 'Can you clarify the budget line?',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created',
      content: {
        'application/json': {
          schema: ApprovalClarificationFlowMessagesShowResponseSchema,
          example: {
            approval_request_id: '01ARZ3NDEKTSV4RRFFQ69G5FAV',
            clarification_flow_messages: [
              {
                author: {
                  avatar: 'https://company.zendesk.com/system/photos/12345/avatar.png',
                  id: 12345,
                  name: 'Jane Doe',
                  role: 'end_user',
                },
                created_at: '2026-09-29T14:32:00Z',
                id: 'msg_123',
                message: 'Can you clarify the budget line?',
                via: 'SUPPORT',
              },
            ],
          },
        },
      },
    },
    400: {
      description: 'Bad Request - the via parameter is invalid',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({ message: z.string().exactOptional(), title: z.string().exactOptional() })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
          example: {
            error: {
              message: 'You passed an invalid value for the via attribute.',
              title: 'Invalid attribute',
            },
          },
        },
      },
    },
    403: {
      description:
        'The current user is not permitted to comment on this approval request, SLACK commenting is not enabled for the account, or the clarification flow feature is not enabled',
      content: {
        'application/json': {
          schema: z.object({ errors: z.string().exactOptional() }).openapi({ required: [] }),
          example: { errors: 'Access denied' },
        },
      },
    },
    404: {
      description: 'The approval request could not be found',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({ message: z.string().exactOptional(), title: z.string().exactOptional() })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
          example: {
            error: {
              message:
                "You've reached this page because what you were looking for does not exist or there's been an error.",
              title: 'Not Found',
            },
          },
        },
      },
    },
    422: {
      description:
        'The message could not be added. The `errors` field is an array of validation messages\nwhen the approval request is no longer active, or a single string paired with an\n`error` code when the comment limit has been reached.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Present only when the comment limit has been reached. Value is always `CommentLimitExceeded`',
                }),
              errors: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'Validation errors (array), or the comment-limit message (string)',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            comment_limit_exceeded: {
              summary: 'The clarification thread has reached the maximum number of comments',
              value: {
                error: 'CommentLimitExceeded',
                errors: 'Comment limit reached, approvers can still approve or deny.',
              },
            },
            default: {
              summary: 'The approval request is no longer active',
              value: {
                errors: ['This approval request has already been withdrawn and cannot be updated.'],
              },
            },
          },
        },
      },
    },
  },
})

