export const getApiV2AuditLogsRoute = createRoute({
  method: 'get',
  path: '/api/v2/audit_logs',
  tags: ['Audit Logs'],
  summary: 'List Audit Logs',
  description:
    '#### Allowed For\n\n* Admins on accounts that have audit log access\n\n#### Pagination\n\n* Cursor pagination (recommended)\n* Offset pagination\n\nSee [Pagination](/api-reference/introduction/pagination/).\n\nReturns a maximum of 100 records per page.\n\n#### Filtering by multiple values\n\nTo filter by multiple values for the same field, repeat the filter parameter and append empty square brackets "[]" to the name of each repeated parameter. For example, to return audit logs where `action` is "create", "update", or "destroy":\n\n`/api/v2/audit_logs?filter[action][]=create&filter[action][]=update&filter[action][]=destroy`\n',
  operationId: 'ListAuditLogs',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          'ids[]': z
            .preprocess(
              (val) => (val === undefined || Array.isArray(val) ? val : [val]),
              z.array(
                z
                  .preprocess((val) => {
                    if (
                      typeof val !== 'string' ||
                      !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                    )
                      return val
                    if (/^-?\d+$/.test(val)) return BigInt(val)
                    const num = Number(val)
                    return Number.isSafeInteger(num) ? BigInt(num) : val
                  }, z.int64())
                  .openapi({ type: 'integer', format: 'int64' }),
              ),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'ids[]',
                in: 'query',
                description:
                  'Filters audit logs by id. To specify multiple ids, repeat the `ids[]` parameter. For example, `?ids[]=1&ids[]=2`',
                style: 'form',
                explode: true,
                schema: { type: 'array', items: { type: 'integer', format: 'int64' } },
                required: false,
              },
            }),
          'filter[source_type]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[source_type]',
                in: 'query',
                description: 'Filter audit logs by the source type. For example, user or rule',
                schema: { type: 'string' },
                required: false,
              },
            }),
          'filter[source_id]': z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[source_id]',
                in: 'query',
                description:
                  'Filter audit logs by the source id. Requires `filter[source_type]` to also be set',
                schema: { type: 'integer', format: 'int64' },
                required: false,
              },
            }),
          'filter[actor_id]': z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[actor_id]',
                in: 'query',
                description: 'Filter audit logs by the actor id',
                schema: { type: 'integer', format: 'int64' },
                required: false,
              },
            }),
          'filter[ip_address]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[ip_address]',
                in: 'query',
                description: 'Filter audit logs by the ip address',
                schema: { type: 'string' },
                required: false,
              },
            }),
          'filter[created_at]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[created_at]',
                in: 'query',
                description:
                  'Filter audit logs by the time of creation. When used, you must specify `filter[created_at]` twice in your request, first with the start time and again with an end time',
                schema: { type: 'string' },
                required: false,
              },
            }),
          'filter[action]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[action]',
                in: 'query',
                description: 'Filter audit logs by the action',
                schema: { type: 'string' },
                required: false,
              },
            }),
          sort_by: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'sort_by',
                in: 'query',
                description:
                  'Offset pagination only. Sort audit logs. Default is `sort_by=created_at`',
                schema: { type: 'string' },
                required: false,
              },
            }),
          sort_order: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'sort_order',
                in: 'query',
                description:
                  'Offset pagination only. Sort audit logs. Default is `sort_order=desc`',
                schema: { type: 'string' },
                required: false,
              },
            }),
          sort: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'sort',
                in: 'query',
                description:
                  'Cursor pagination only. Sort audit logs. Default is `sort=-created_at`',
                schema: { type: 'string' },
                required: false,
              },
            }),
          page: CursorPaginationPageParamsSchema,
          per_page: PerPageParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: AuditLogsResponseSchema,
          examples: { default: AuditLogsResponseExampleExample },
        },
      },
    },
  },
})

