export const postApiV2BrandsBrandIdUserMigrationsRoute = createRoute({
  method: 'post',
  path: '/api/v2/brands/{brand_id}/user_migrations',
  tags: ['Brand User Migrations', 'Brands'],
  summary: 'Create Brand User Migration',
  description:
    "Creates a brand user migration for the specified brand. Only one active\nmigration may exist per account at a time.\n\nThe `direction.from.scope` must match the brand's current user separation\nsetting, and the from/to scopes must differ.\n\n#### Allowed For\n\n* Admins\n\n#### Availability\n\nAvailable on accounts with Department Spaces.\n",
  operationId: 'CreateBrandUserMigration',
  request: {
    params: z.object({ brand_id: BrandIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: BrandUserMigrationCreateRequestSchema,
          examples: { default: BrandUserMigrationCreateRequestExampleExample },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Migration created',
      content: {
        'application/json': {
          schema: BrandUserMigrationResponseSchema,
          examples: { default: BrandUserMigrationExampleExample },
        },
      },
    },
    409: {
      description:
        'Concurrent requests for migration creation were received. An active\nmigration already exists for the account; retrying after the existing\nmigration completes or is aborted should succeed. The normal failure\nfor an existing active migration is 422.\n',
      content: {
        'application/json': {
          schema: z
            .object({ description: z.string().exactOptional(), error: z.string().exactOptional() })
            .openapi({ required: [] }),
          examples: { default: BrandUserMigrationConflictExampleExample },
        },
      },
    },
    422: {
      description:
        "Validation failed. Returned when the account has an active migration\nthat cannot be superseded, when `direction.from.scope` does not match\nthe brand's current user separation setting, or when the from/to\nscopes do not differ.\n\nA reversal is supported without error: creating a migration in the\nexact opposite direction of an active `in_progress` migration aborts\nthat migration and creates the new one.\n",
      content: {
        'application/json': {
          schema: z
            .object({
              description: z.string().exactOptional(),
              details: z
                .record(
                  z.string(),
                  z.array(
                    z.object({ description: z.string().exactOptional() }).openapi({ required: [] }),
                  ),
                )
                .exactOptional(),
              error: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

