export const getApiV2CountriesIdJsonRoute = createRoute({
  method: 'get',
  path: '/api/v2/countries/{id}.json',
  tags: ['Countries'],
  summary: 'Show Country',
  description:
    'Returns details for a specific country by ID.\n\nThis endpoint is publicly accessible and does not require authentication.\n\n#### Allowed For\n\n* Anyone\n',
  operationId: 'ShowCountry',
  request: {
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            description: 'The ID of the country',
            required: true,
            schema: { type: 'integer' },
            example: 1,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .object({ country: CountryObjectSchema.exactOptional() })
            .openapi({ required: [] }),
          examples: {
            default: {
              value: {
                country: {
                  calling_code: '93',
                  code: 'AF',
                  id: 1,
                  name: 'Afghanistan',
                  region: 'APAC',
                },
              },
            },
          },
        },
      },
    },
  },
})

