export const getApiV2CustomObjectsCustomObjectKeyRecordsRoute = createRoute({
  method: 'get',
  path: '/api/v2/custom_objects/{custom_object_key}/records',
  tags: ['Custom Object Records'],
  summary: 'List Custom Object Records',
  description:
    'Lists all undeleted custom object records for the specified object.\n\nIf the object has a parent field with `cascade_permissions_enabled`, non-admin agents receive a `403 Forbidden` response. Use the [Filtered Search endpoint](#filtered-search-of-custom-object-records) with a filter on the parent field instead.\n\n #### Pagination\n\n* [Cursor pagination](/api-reference/introduction/pagination/#cursor-pagination) only.\n#### Allowed For\n* Agents',
  operationId: 'ListCustomObjectRecords',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z.object({
      'filter[ids]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[ids]',
            in: 'query',
            description:
              'Optional comma-separated list of ids to filter records by. If one or more ids are specified, only matching records are returned. The ids must be unique and are case sensitive.',
            schema: { type: 'string' },
            examples: {
              multipleIds: { summary: 'Example of multiple ids', value: 'id_1,id_2,id_3' },
              oneId: { summary: 'Example of a single id', value: 'id_1' },
            },
            required: false,
          },
        }),
      'filter[external_ids]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[external_ids]',
            in: 'query',
            description:
              'Optional comma-separated list of external ids to filter records by. If one or more ids are specified, only matching records are returned. The ids must be unique and are case sensitive.',
            schema: { type: 'string' },
            examples: {
              multipleIds: { summary: 'Example of multiple ids', value: 'ex_id_1,ex_id_2,ex_id_3' },
              oneId: { summary: 'Example of a single id', value: 'ex_id_1' },
            },
            required: false,
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            description:
              'One of `id`, `updated_at`, `-id`, or `-updated_at`. The `-` denotes the sort will be descending.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[before]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.before_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[after]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.after_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description:
              'Specifies how many records should be returned in the response. You can specify up to 100 records per page.\n',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: CustomObjectRecordsResponseSchema,
          examples: { default: CustomObjectRecordsIndexResponseExampleExample },
        },
      },
    },
  },
})

