export const deleteApiV2CustomObjectsCustomObjectKeyRecordsRoute = createRoute({
  method: 'delete',
  path: '/api/v2/custom_objects/{custom_object_key}/records',
  tags: ['Custom Object Records'],
  summary: 'Delete Custom Object Record by External Id Or Name',
  description:
    "Deletes a record with the specified external id, name, or unique field value. Specify only one identifier per request.\n\n* The `is_unique` property on the custom object's name field must be enabled in order to delete by name.\n* To delete by a unique field, send the field's key as the query parameter, for example `?vin=1HGCM82633A004352`. The field's `is_unique` property must be enabled.\n\nIf the record is a parent in a parent-child relationship, all associated child records are also deleted asynchronously via a background job.\n#### Allowed For\n* Agents\n",
  operationId: 'DeleteCustomObjectRecordByExternalIdOrName',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const open: string[] = ['unique_field_value']
        const taken: string[] = ['external_id', 'name']
        for (const [key, item] of Object.entries(val)) {
          if (!taken.includes(key)) {
            for (const owner of open) {
              group(owner)[key] = item
            }
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          external_id: CustomObjectRecordExternalIdParamsSchema,
          name: CustomObjectRecordNameParamsSchema,
          unique_field_value: CustomObjectRecordUniqueFieldValueParamsSchema,
        }),
      ),
  },
  responses: { 204: { description: 'No content response' } },
})

export const patchApiV2CustomObjectsCustomObjectKeyRecordsRoute = createRoute({
  method: 'patch',
  path: '/api/v2/custom_objects/{custom_object_key}/records',
  tags: ['Custom Object Records'],
  summary: 'Create or Update Custom Object Record',
  description:
    "Creates or updates a custom object record based on the provided external id, name, or unique field value. If a record exists for the given identifier, the endpoint updates it. Only the specified attributes are updated. Otherwise, the endpoint creates a new record with the provided identifier and other attributes. Specify only one identifier per request.\n\n* The `is_unique` property on the custom object's name field must be enabled in order to update or create by name.\n* To update or create by a unique field, send the field's key as the query parameter, for example `?vin=1HGCM82633A004352`. The field's `is_unique` property must be enabled. A new record is created with that value in the field.\n#### Allowed For\n* Agents\n",
  operationId: 'UpsertCustomObjectRecordByExternalIdOrName',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const open: string[] = ['unique_field_value']
        const taken: string[] = ['external_id', 'name']
        for (const [key, item] of Object.entries(val)) {
          if (!taken.includes(key)) {
            for (const owner of open) {
              group(owner)[key] = item
            }
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          external_id: CustomObjectRecordExternalIdParamsSchema,
          name: CustomObjectRecordNameParamsSchema,
          unique_field_value: CustomObjectRecordUniqueFieldValueParamsSchema,
        }),
      ),
    body: {
      content: {
        'application/json': {
          schema: CustomObjectRecordsUpsertRequestSchema,
          examples: { default: CustomObjectRecordsUpsertRequestExampleExample },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: CustomObjectRecordResponseSchema,
          examples: { default: CustomObjectRecordsUpsertResponseExampleExample },
        },
      },
    },
  },
})

