export const getApiV2CustomObjectsCustomObjectKeyRecordsAutocompleteRoute = createRoute({
  method: 'get',
  path: '/api/v2/custom_objects/{custom_object_key}/records/autocomplete',
  tags: ['Custom Object Records'],
  summary: 'Autocomplete Custom Object Record Search',
  description:
    'Retrieves an array of custom object records that have a field value that matches the value specified in the `name` parameter.\n\nIf the object has a parent field with `cascade_permissions_enabled`, the request must be made in the context of a cascade parent field using the `field_id` and `source` parameters.\n\n#### Pagination\n\n* [Cursor pagination](/api-reference/introduction/pagination/#cursor-pagination) only.\n* Returns the first 10,000 records sorted by relevancy with page limits.\n#### Allowed For\n* Agents',
  operationId: 'AutocompleteCustomObjectRecordSearch',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['filter[dynamic_values]']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          name: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'name',
                in: 'query',
                description: 'Part of a name of the record you are searching for',
                schema: { type: 'string' },
                required: false,
              },
            }),
          'page[before]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'page[before]',
                in: 'query',
                description:
                  "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.before_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
                schema: { type: 'string' },
                required: false,
              },
            }),
          'page[after]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'page[after]',
                in: 'query',
                description:
                  "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.after_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
                schema: { type: 'string' },
                required: false,
              },
            }),
          'page[size]': z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'page[size]',
                in: 'query',
                description:
                  'The number of records to return in the response. You can specify up to 100 records per page.\n',
                schema: { type: 'integer' },
                required: false,
              },
            }),
          field_id: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'field_id',
                in: 'query',
                description:
                  'The id of the lookup field. If the field has a relationship filter, the filter is applied to the results. Must be used with `source` param.\n',
                schema: { type: 'string' },
                required: false,
              },
            }),
          source: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'source',
                in: 'query',
                description:
                  'One of "zen:user", "zen:ticket", "zen:organization", or "zen:custom_object:CUSTOM_OBJECT_KEY". Represents the object `field_id` belongs to. Must be used with field_id param.\n',
                schema: { type: 'string' },
                required: false,
              },
            }),
          'filter[dynamic_values]': z
            .record(
              z.string(),
              z.preprocess(
                (val) =>
                  typeof val === 'string' &&
                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                    ? Number(val)
                    : val,
                z.int(),
              ),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[dynamic_values]',
                in: 'query',
                description:
                  'Provided values to be used with [dynamic filters](/api-reference/ticketing/lookup_relationships/lookup_relationships/#using-dynamic-filters).\n',
                style: 'deepObject',
                explode: true,
                schema: {
                  type: 'object',
                  additionalProperties: { type: 'integer' },
                  example: { ticket_brand_id: 456, ticket_fields_123: 123 },
                },
                required: false,
              },
              example: { ticket_brand_id: 456, ticket_fields_123: 123 },
            }),
          requester_id: z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .exactOptional()
            .openapi({
              param: {
                name: 'requester_id',
                in: 'query',
                description: 'The id of the requester. For use with dynamic filters.\n',
                schema: { type: 'integer', format: 'int64' },
                example: 264817272,
                required: false,
              },
            }),
          assignee_id: z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .exactOptional()
            .openapi({
              param: {
                name: 'assignee_id',
                in: 'query',
                description: 'The id of the selected assignee. For use with dynamic filters.\n',
                schema: { type: 'integer', format: 'int64' },
                example: 7334148660734,
                required: false,
              },
            }),
          organization_id: z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .exactOptional()
            .openapi({
              param: {
                name: 'organization_id',
                in: 'query',
                description:
                  'The id of the organization the requester belongs to. For use with dynamic filters.\n',
                schema: { type: 'integer', format: 'int64' },
                example: 5633330889598,
                required: false,
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: CustomObjectRecordsResponseSchema,
          examples: { default: CustomObjectRecordsAutocompleteResponseExampleExample },
        },
      },
    },
  },
})

export const getApiV2CustomObjectsCustomObjectKeyRecordsCountRoute = createRoute({
  method: 'get',
  path: '/api/v2/custom_objects/{custom_object_key}/records/count',
  tags: ['Custom Object Records'],
  summary: 'Count Custom Object Records',
  description:
    'Returns a total count of records for a specific custom object as well as the time the count was refreshed.\n\nIf the object has a parent field with `cascade_permissions_enabled`, non-admin agents receive a `403 Forbidden` response. Use the [Filtered Search endpoint](/api-reference/custom-data/custom-objects/custom_object_records/#filtered-search-of-custom-object-records) with a filter on the parent field instead.\n\n#### Allowed For\n* Agents',
  operationId: 'CountCustomObjectRecords',
  request: { params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }) },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z
                .record(
                  z.string(),
                  z
                    .object({
                      refreshed_at: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'The time the last count was performed',
                          readOnly: true,
                        }),
                      value: z
                        .int()
                        .exactOptional()
                        .openapi({
                          description:
                            'Number of records at the time of the latest count operation',
                          readOnly: true,
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            default: { value: { count: { refreshed_at: '2022-09-02T22:44:35Z', value: 7 } } },
          },
        },
      },
    },
  },
})

export const getApiV2CustomObjectsCustomObjectKeyRecordsSearchRoute = createRoute({
  method: 'get',
  path: '/api/v2/custom_objects/{custom_object_key}/records/search',
  tags: ['Custom Object Records'],
  summary: 'Search Custom Object Records',
  description:
    'Returns an array of custom object records where the search query matches the values in Text Fields, Multi Line Text fields, and RegExp fields. To find records in other fields, use the [Filtered Search API](/api-reference/custom-data/custom-objects/custom_object_records/#filtered-search-of-custom-object-records) endpoint.\n\nIf the object has a parent field with `cascade_permissions_enabled`, non-admin agents receive a `403 Forbidden` response. Use the [Filtered Search endpoint](/api-reference/custom-data/custom-objects/custom_object_records/#filtered-search-of-custom-object-records) with a filter on the parent field instead.\n\n#### Pagination\n\n* [Cursor pagination](/api-reference/introduction/pagination/#cursor-pagination) only.\n* Returns the records sorted by relevancy with page limits. Without a `sort` parameter, only the first 10,000 records are returned. With a `sort` parameter, all records are returned.\n#### Allowed For\n* Agents',
  operationId: 'SearchCustomObjectRecords',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z.object({
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'query',
            in: 'query',
            description:
              "The query parameter is used to search text-based fields for records that match specific query terms.\nThe query can be multiple words or numbers. Every record that matches the beginning of any word or number in the query string is returned.<br/><br/>\n\nFuzzy search is supported for the following text-based field types: Text fields, Multi Line Text fields, and RegExp fields.<br/><br/>\n\nFor example, you might want to search for records related to Tesla vehicles: `query=Tesla`. In this example the API would return every record for the given custom object where any of the supported text fields contain the word 'Tesla'.<br/><br/>\n\nYou can include multiple words or numbers in your search. For example: `query=Tesla Honda 2020`. This search phrase would be URL encoded as `query=Tesla%20Honda%202020` and return every record for the custom object for which any of the supported text fields contained 'Tesla', 'Honda', or '2020'.\n",
            schema: { type: 'string' },
            example: 'jdoe',
            required: false,
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            description:
              'One of `name`, `created_at`, `updated_at`, `-name`, `-created_at`, or `-updated_at`. The `-` denotes the sort will be descending. Defaults to sorting by relevance.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[before]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.before_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[after]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.after_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description:
              'Specifies how many records should be returned in the response. You can specify up to 100 records per page.\n',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: CustomObjectRecordsResponseSchema,
          examples: { default: CustomObjectRecordsSearchResponseExampleExample },
        },
      },
    },
  },
})

export const postApiV2CustomObjectsCustomObjectKeyRecordsSearchRoute = createRoute({
  method: 'post',
  path: '/api/v2/custom_objects/{custom_object_key}/records/search',
  tags: ['Custom Object Records'],
  summary: 'Filtered Search of Custom Object Records',
  description:
    'Returns an array of custom object records that meet the search and filter criteria. For simple searches limited to only text fields and no complex logic, use the [Search Custom Object Records API](/api-reference/custom-data/custom-objects/custom_object_records/#search-custom-object-records) endpoint.\n\nIf the object has a parent field with `cascade_permissions_enabled`, non-admin agents must include a filter on the parent field (for example, `"custom_object_fields.parent_field_key": { "$eq": "parent_record_id" }`). Requests without a parent filter return `403 Forbidden`.\n\nFilters can contain either an individual [comparison object](#comparison-object) or an array of filter expressions within logical namespaces. Filter expressions can themselves be either comparison objects or `$and` / `$or` groups, so logical operators can be nested to build complex Boolean queries.\n\nA filter is a JSON object that has the following properties:\n\n| Name      | Type   | Required | Description\n| --------- | ------ | -------- | -----------\n| ATTRIBUTE | object | no       | A [comparison object](#comparison-object) specifying an attribute value condition to be met for records to match.<br/><br/>Examples are marked below.\n| $and      | array  | no       | Array of filter expressions combined with logical AND. Each element may be a comparison object or a nested `$and` / `$or` group.\n| $or       | array  | no       | Array of filter expressions combined with logical OR. Each element may be a comparison object or a nested `$and` / `$or` group.\n\nLimits for nested `$and` / `$or` groups:\n\n* Maximum nesting depth: `5` (outermost `$and` / `$or` counts as level 1). Exceeding it returns `422 Invalid Condition`.\n* Attribute keys cannot share a level with `$and` / `$or` once the payload contains any `$and` / `$or` nested inside another `$and` / `$or`. The request returns `422 Invalid Condition`; wrap the attribute inside the group instead.\n\n##### Examples\n\n```js\n{\n  "filter": {\n    "custom_object_fields.field_key": { "$eq": "value" } // ATTRIBUTE\n  }\n}\n```\n\n```js\n{\n  "filter": {\n    "$or": [\n      { "custom_object_fields.field_key": { "$eq": "value" } }, // ATTRIBUTE\n      { "external_id": { "$eq": "Record123" } } // ATTRIBUTE\n    ]\n  }\n}\n```\n\n```js\n// Nested $and / $or\n{\n  "filter": {\n    "$and": [\n      { "custom_object_fields.contract_term_months": { "$gt": 5 } },\n      {\n        "$or": [\n          { "custom_object_fields.status": { "$eq": "active" } },\n          { "custom_object_fields.status": { "$eq": "pending" } }\n        ]\n      }\n    ]\n  }\n}\n```\n\n#### Comparison Object\n\nA comparison object defines a condition a record must meet to be considered a match. The condition is based on an attribute value or object type.\n\nA comparison object is a JSON object that has the following properties:\n\n| Name      | Type          | Required | Description\n| --------- | ------------- | -------- | -----------\n| FIELD_KEY | string        | yes      | When filtering on a custom field, they must be namedspaced with `custom_object_fields.`. ex. `custom_object_fields.field_key`<br/><br/>When filtering on a standard field, no namespace is required. The following fields are considered standard: `created_at`, `updated_at`, `created_by_user`, `updated_by_user`, `name`, `external_id`\n| OPERATOR  | string        | yes      | [Supported operators](/documentation/custom-data/v2/searching-custom-object-records/) vary by the value\'s data type\n| VALUE     | string, array | yes      | The value you\'re filtering for\n\n* Date values should be in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format.\n\n#### Pagination\n\n* [Cursor pagination](/api-reference/introduction/pagination/#cursor-pagination) only.\n* Returns the records sorted by relevancy with page limits. Without a `sort` parameter, only the first 10,000 records are returned. With a `sort` parameter, all records are returned.\n\n#### Allowed For\n\n* Agents\n* End users (when an admin [configures](https://support.zendesk.com/hc/en-us/articles/6034260247066) the custom object to be accessible to end users)',
  operationId: 'FilteredSearchCustomObjectRecords',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z.object({
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'query',
            in: 'query',
            description:
              "The query parameter is used to search text-based fields for records that match specific query terms.\nThe query can be multiple words or numbers. Every record that matches the beginning of any word or number in the query string is returned.<br/><br/>\n\nFuzzy search is supported for the following text-based field types: Text fields, Multi Line Text fields, and RegExp fields.<br/><br/>\n\nFor example, you might want to search for records related to Tesla vehicles: `query=Tesla`. In this example the API would return every record for the given custom object where any of the supported text fields contain the word 'Tesla'.<br/><br/>\n\nYou can include multiple words or numbers in your search. For example: `query=Tesla Honda 2020`. This search phrase would be URL encoded as `query=Tesla%20Honda%202020` and return every record for the custom object for which any of the supported text fields contained 'Tesla', 'Honda', or '2020'.\n",
            schema: { type: 'string' },
            example: 'jdoe',
            required: false,
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            description:
              'One of "name", "created_at", "updated_at", "-name", "-created_at", or "-updated_at". The "-" denotes the sort will be descending. Defaults to sorting by relevance.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[before]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.before_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[after]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.after_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description:
              'Specifies how many records should be returned in the response. You can specify up to 100 records per page.\n',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z.union([
            CustomObjectRecordsFilteredSearchRequestBasicSchema,
            CustomObjectRecordsFilteredSearchRequestComplexSchema,
          ]),
          examples: {
            default: CustomObjectRecordsFilteredSearchRequestExampleExample,
            nested: CustomObjectRecordsFilteredSearchNestedRequestExampleExample,
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: CustomObjectRecordsResponseSchema,
          examples: { default: CustomObjectRecordsSearchResponseExampleExample },
        },
      },
    },
  },
})

export const getApiV2CustomObjectsCustomObjectKeyRecordsShowByUniqueIdentifierRoute = createRoute({
  method: 'get',
  path: '/api/v2/custom_objects/{custom_object_key}/records/show_by_unique_identifier',
  tags: ['Custom Object Records'],
  summary: 'Show Custom Object Record by Unique Identifier',
  description:
    "Returns a custom object record identified by its external id, its name, or the value of one of the custom object's unique fields. Send exactly one identifier per request.\n\n* To identify the record by name, the `is_unique` property on the custom object's name field must be enabled.\n* To identify the record by a unique field, send the field's key as the query parameter, for example `?vin=1HGCM82633A004352`. The field's `is_unique` property must be enabled. For a unique lookup field, the value is the id of the record the field references.\n\nReturns a `400 Bad Request` if more than one identifier is sent, if `name` is sent and the name field isn't unique, or if no identifier is sent. A parameter that isn't the key of a unique field doesn't count as an identifier. Returns a `404 Not Found` if no record matches.\n#### Allowed For\n* Agents\n",
  operationId: 'ShowCustomObjectRecordByUniqueIdentifier',
  request: {
    params: z.object({ custom_object_key: CustomObjectKeyParamsSchema }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const open: string[] = ['unique_field_value']
        const taken: string[] = ['external_id', 'name']
        for (const [key, item] of Object.entries(val)) {
          if (!taken.includes(key)) {
            for (const owner of open) {
              group(owner)[key] = item
            }
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          external_id: CustomObjectRecordExternalIdParamsSchema,
          name: CustomObjectRecordNameParamsSchema,
          unique_field_value: CustomObjectRecordUniqueFieldValueParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'Custom Object Record',
      content: {
        'application/json': {
          schema: CustomObjectRecordResponseSchema,
          examples: { default: CustomObjectRecordsCreateResponseExampleExample },
        },
      },
    },
  },
})

