export const postApiV2CustomStatusesCustomStatusIdTicketFormStatusesRoute = createRoute({
  method: 'post',
  path: '/api/v2/custom_statuses/{custom_status_id}/ticket_form_statuses',
  tags: ['Custom Ticket Statuses', 'Ticket Form Statuses'],
  summary: 'Create Ticket Form Statuses for a Custom Status',
  description:
    'Creates one or many tickets form status associations for a custom status.\n\n#### Allowed For\n\n* Admins\n',
  operationId: 'CreateTicketFormStatusesForCustomStatus',
  request: {
    params: z.object({ custom_status_id: CustomStatusIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              ticket_form_status: z
                .array(
                  z
                    .object({
                      ticket_form_id: z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .exactOptional()
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          description: 'The id of the ticket form',
                          example: 1,
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          example: {
            ticket_form_status: [
              { ticket_form_id: 1 },
              { ticket_form_id: 2 },
              { ticket_form_id: 3 },
            ],
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: TicketFormStatusesResponseSchema,
          examples: { default: TicketFormStatusesResponseExampleExample },
        },
      },
    },
  },
})

