export const postApiV2EndUsersUserIdIdentitiesRoute = createRoute({
  method: 'post',
  path: '/api/v2/end_users/{user_id}/identities',
  tags: ['User Identities'],
  summary: 'Create End User Identity',
  description:
    'Adds an identity to an end user\'s profile.\n\nSupported identity types for end users:\n\n| Type             | Example |\n| ---------------- | ------- |\n| email            | `{ "type" : "email", "value" : "someone@example.com" }` |\n| phone_number     | `{ "type" : "phone_number", "value" : "+1 555-123-4567" }` |\n\n#### Allowed For\n\n* Verified end users\n',
  operationId: 'CreateEndUserIdentity',
  request: {
    params: z.object({ user_id: UserIdParamsSchema }),
    query: z.object({
      'type[]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.enum(['email', 'phone_number'])),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'type[]',
            in: 'query',
            description:
              'Filters results by one or more identity types using the format `?type[]={type}&type[]={type}`',
            style: 'form',
            explode: true,
            schema: { type: 'array', items: { type: 'string', enum: ['email', 'phone_number'] } },
            required: false,
          },
        }),
      brand_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'brand_id',
            in: 'query',
            description:
              'When brand separation is enabled, associates the new identity with the specified brand.',
            schema: { type: 'integer', format: 'int64' },
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: EndUserIdentityCreateRequestSchema,
          examples: { default: UserIdentityCreateRequestExampleExample },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created response',
      content: {
        'application/json': {
          schema: UserIdentityResponseSchema,
          examples: { default: UserIdentityCreateResponseExampleExample },
        },
      },
    },
  },
})

