export const getApiV2ItAssetManagementAssetsRoute = createRoute({
  method: 'get',
  path: '/api/v2/it_asset_management/assets',
  tags: ['ITAM Assets'],
  summary: 'List Assets',
  description:
    'Lists all assets for all asset types.\n\n#### Filtering\n\nUse the `filter[ids]` or `filter[external_ids]` query parameters to filter results by asset IDs or external IDs. Both parameters accept comma-separated values.\n\n#### Pagination\n\n* [Cursor pagination](/api-reference/introduction/pagination/#cursor-pagination) only.\n\n#### Allowed For\n\n* Agents',
  operationId: 'ListItamAssets',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          page: CursorPaginationPageParamsSchema,
          'filter[ids]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[ids]',
                in: 'query',
                description:
                  'Optional comma-separated list of ids to filter assets by. If one or more ids are specified, only matching assets are returned. The ids must be unique and are case sensitive.',
                schema: { type: 'string' },
                examples: {
                  multipleIds: {
                    summary: 'Example of multiple ids',
                    value: '01HGW2N7KBHZ3T4Y6X9RQV5MPC,01HGW2N7KBHZ3T4Y6X9RQV5MPD',
                  },
                  oneId: { summary: 'Example of a single id', value: '01HGW2N7KBHZ3T4Y6X9RQV5MPC' },
                },
                required: false,
              },
            }),
          'filter[external_ids]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'filter[external_ids]',
                in: 'query',
                description:
                  'Optional comma-separated list of external ids to filter assets by. If one or more external ids are specified, only matching assets are returned. The external ids must be unique and are case sensitive.',
                schema: { type: 'string' },
                examples: {
                  multipleIds: {
                    summary: 'Example of multiple external ids',
                    value: 'my-external-id-123,my-external-id-456',
                  },
                  oneId: {
                    summary: 'Example of a single external id',
                    value: 'my-external-id-123',
                  },
                },
                required: false,
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: ItamAssetsResponseSchema,
          examples: { default: ItamAssetsIndexResponseExampleExample },
        },
      },
    },
    400: {
      description:
        'Returned when the combined count of `filter[ids]` and `filter[external_ids]` exceeds 100, or if `page[size]` is less than 1 or greater than 100, or if both `page[after]` and `page[before]` are provided.',
      content: {
        'application/json': {
          schema: z
            .object({ description: z.string().exactOptional(), error: z.string().exactOptional() })
            .openapi({ required: [] }),
          examples: {
            default: {
              summary: 'Too many filter IDs',
              value: { error: 'Too many IDs requested. Maximum is 100 total.' },
            },
            invalidPagination: {
              summary: 'Invalid pagination parameter',
              value: {
                description: 'Pass either `page[after]` or `page[before]`, not both',
                error: 'InvalidPaginationParameter',
              },
            },
          },
        },
      },
    },
  },
})

