export const getApiV2OrganizationsOrganizationIdTicketsCountRoute = createRoute({
  method: 'get',
  path: '/api/v2/organizations/{organization_id}/tickets/count',
  tags: ['Tickets'],
  summary: 'Count Organization Tickets',
  description:
    'Returns an approximate count of tickets for a specific organization. If the count exceeds 100,000, it is updated every 24 hours.\n\nThe `count[refreshed_at]` property is a timestamp that indicates when the count was last updated.\n\n**Note**: When the count exceeds 100,000, `count[refreshed_at]` may occasionally be null.\nThis indicates that the count is being updated in the background, and `count[value]` is limited to 100,000 until the update is complete.\n\n#### Allowed For\n* Agents\n',
  operationId: 'CountOrganizationTickets',
  request: { params: z.object({ organization_id: OrganizationIdParamsSchema }) },
  responses: {
    200: {
      description: 'Count of tickets',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z
                .object({
                  refreshed_at: z.iso.datetime({ offset: true }).exactOptional(),
                  value: z.int().exactOptional(),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
          examples: {
            default: { value: { count: { refreshed_at: '2020-04-06T02:18:17Z', value: 102 } } },
          },
        },
      },
    },
  },
})

