export const getApiV2RemoteAuthenticationsRoute = createRoute({
  method: 'get',
  path: '/api/v2/remote_authentications',
  tags: ['Remote Authentications'],
  summary: 'List Remote Authentications',
  description: '#### Allowed For\n\n* Admins\n',
  operationId: 'ListRemoteAuthentications',
  request: {
    query: z.object({
      brand_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'brand_id',
            in: 'query',
            description:
              'When brand separation is enabled, scopes the remote authentications to the specified brand.\n',
            schema: { type: 'integer', format: 'int64' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: RemoteAuthenticationsResponseSchema,
          examples: { default: RemoteAuthenticationsResponseExampleExample },
        },
      },
    },
  },
})

