export const getApiV2RoutingAgentsInstanceValuesRoute = createRoute({
  method: 'get',
  path: '/api/v2/routing/agents/instance_values',
  tags: ['Skill Based Routing'],
  summary: 'List Attribute Values for Many Agents',
  description:
    "Accepts a comma-separated list of up to 100 agent ids and returns attribute values for each agent in the list.\n\n#### Allowed For\n* Admins\n* [Agents in custom role with permission to manage skills](https://support.zendesk.com/hc/en-us/articles/4408882153882)\n\n#### Pagination\n* [Cursor pagination](/api-reference/introduction/pagination/#cursor-pagination) only.\nNote: `page[before]` and `page[after]` can't be used together in the same request.\n",
  operationId: 'ListManyAgentsAttributeValues',
  request: {
    query: z.object({
      'filter[agent_ids]': z
        .string()
        .openapi({
          param: {
            name: 'filter[agent_ids]',
            in: 'query',
            description: 'A comma-separated list of agent ids',
            required: true,
            schema: { type: 'string' },
            example: '224,225',
          },
        }),
      'page[before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[before]',
            in: 'query',
            description:
              'A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.before_cursor` value from a previous request.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[after]',
            in: 'query',
            description:
              'A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.after_cursor` value from a previous request.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description: 'The number of items to return per page',
            schema: { type: 'integer', format: 'int32', minimum: 1, maximum: 100 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: ManySkillBasedRoutingAttributeValuesResponseSchema,
          examples: { default: ManySkillBasedRoutingAttributeValuesResponseExampleExample },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: SkillBasedRoutingAttributeValuesErrorSchema,
          examples: { default: ManySkillBasedRoutingAttributeValuesErrorExampleExample },
        },
      },
    },
  },
})

