export const getApiV2RoutingRequirementsFulfilledRoute = createRoute({
  method: 'get',
  path: '/api/v2/routing/requirements/fulfilled',
  tags: ['Skill Based Routing'],
  summary: 'List Tickets Fulfilled by a User',
  description:
    "Returns a list of ticket ids that contain attributes matching the current user's attributes. Accepts a `ticket_ids` parameter for relevant tickets to check for matching attributes.\n\n#### Allowed For\n\n* Agents\n* Light agents and contributors\n",
  operationId: 'ListTicketsFullfilledByUser',
  request: {
    query: z.object({
      ticket_ids: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'ticket_ids',
            in: 'query',
            description: 'The IDs of the relevant tickets to check for matching attributes',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            example: 1,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: SkillBasedRoutingTicketFulfilledResponseSchema,
          examples: { default: SkillBasedRoutingTicketFulfilledResponseExampleExample },
        },
      },
    },
  },
})

