export const putApiV2SuspendedTicketsBulkRecoverRoute = createRoute({
  method: 'put',
  path: '/api/v2/suspended_tickets/bulk_recover',
  tags: ['Suspended Tickets'],
  summary: 'Bulk Recover Suspended Tickets',
  description:
    'Enqueues a bulk job to recover multiple suspended tickets. Returns a job status that can be tracked via the Job Statuses API.\n\nUnlike the [Recover Multiple Suspended Tickets](#recover-multiple-suspended-tickets) endpoint which processes tickets synchronously, this endpoint queues an asynchronous job for processing large batches.\n\n#### Allowed For\n\n* Admins and [agents in custom roles with permission](https://support.zendesk.com/hc/en-us/articles/4408882153882#topic_cxn_hig_bd) to manage suspended tickets on Enterprise plans\n* Unrestricted agents on all other plans\n',
  operationId: 'BulkRecoverSuspendedTickets',
  request: {
    query: z.object({
      ids: z
        .string()
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            description: 'Comma-separated list of suspended ticket IDs to recover',
            required: true,
            schema: { type: 'string', example: '1,2,3' },
          },
          example: '1,2,3',
        }),
    }),
    body: {
      description: 'Optional author information for recovered tickets',
      content: {
        'application/json': {
          schema: z
            .object({
              author: z
                .object({
                  email: z
                    .email()
                    .exactOptional()
                    .openapi({ description: 'Email address to identify the author' }),
                  id: z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .exactOptional()
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description: 'User ID to set as the author of recovered tickets',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
          examples: { default: { value: { author: { email: 'user@example.com', id: 12345 } } } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Job successfully enqueued',
      content: {
        'application/json': {
          schema: JobStatusResponseSchema,
          examples: {
            default: {
              value: {
                job_status: {
                  id: '8b726e606741012ffc2d782bcb7848fe',
                  message: null,
                  progress: 0,
                  results: null,
                  status: 'queued',
                  total: 3,
                  url: 'https://example.zendesk.com/api/v2/job_statuses/8b726e606741012ffc2d782bcb7848fe.json',
                },
              },
            },
          },
        },
      },
    },
    422: {
      description: 'Invalid request - missing or malformed parameters',
      content: {
        'application/json': {
          schema: z.object({ error: z.string().exactOptional() }).openapi({ required: [] }),
          examples: { default: { value: { error: 'Invalid parameters' } } },
        },
      },
    },
  },
})

