export const getApiV2TicketAuditsRoute = createRoute({
  method: 'get',
  path: '/api/v2/ticket_audits',
  tags: ['Ticket Audits'],
  summary: 'List All Ticket Audits',
  description:
    'Returns ticket audits. Archived tickets are not included in the response. Use the [List Audits for a Ticket](#list-audits-for-a-ticket) endpoint to\nretrieve audit records for an archived ticket. To learn more about archived tickets, see [About archived tickets](https://support.zendesk.com/hc/en-us/articles/4408887617050).\n\nThis endpoint should not be used for capturing change data. When continually chasing the tail of a cursor, some records will be skipped. For this use case, use the [Incremental Ticket Event Export API](/api-reference/ticketing/ticket-management/incremental_exports/#incremental-ticket-event-export).\n\n#### Allowed For\n\n* Admins\n',
  operationId: 'ListTicketAudits',
  request: {
    query: z.object({
      'page[before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[before]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.before_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[after]',
            in: 'query',
            description:
              "A [pagination cursor](/documentation/api-basics/pagination/paginating-through-lists-using-cursor-pagination) that tells the endpoint which page to start on. It should be a `meta.after_cursor` value from a previous request. Note: `page[before]` and `page[after]` can't be used together in the same request.\n",
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description:
              'Specifies how many records to be returned in the response. You can specify up to 100 records per page.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: TicketAuditsResponseSchema,
          examples: { default: TicketAuditsResponseExampleExample },
        },
      },
    },
  },
})

