export const getApiV2TicketsTicketIdMacrosMacroIdApplyRoute = createRoute({
  method: 'get',
  path: '/api/v2/tickets/{ticket_id}/macros/{macro_id}/apply',
  tags: ['Macros'],
  summary: 'Show Ticket After Changes',
  description:
    "Returns the full ticket object as it would be after applying the macro to the ticket.\nIt doesn't actually change the ticket.\n\nTo get only the ticket fields that would be changed by the macro,\nsee [Show Changes to Ticket](#show-changes-to-ticket).\n\n#### Allowed For\n\n* Agents\n",
  operationId: 'ShowTicketAfterChanges',
  request: {
    params: z.object({
      macro_id: MacroIdParamsSchema,
      ticket_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'ticket_id',
            in: 'path',
            description: 'The ID of the ticket',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            example: 35436,
          },
        }),
    }),
    query: z.object({
      normalize_comment: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'normalize_comment',
            in: 'query',
            description:
              "If true, normalizes the newline formatting of the macro's comment to more closely match the formatting produced by the ticket comment editor",
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success Response',
      content: {
        'application/json': {
          schema: MacroApplyTicketResponseSchema,
          examples: { default: MacroChangesToTicketsResponseExampleExample },
        },
      },
    },
  },
})

