export const getApiV2TriggerCategoriesRoute = createRoute({
  method: 'get',
  path: '/api/v2/trigger_categories',
  tags: ['Trigger Categories'],
  summary: 'List Ticket Trigger Categories',
  description:
    'Returns all the ticket trigger categories in the account.\n\n#### Pagination\n\n* Cursor pagination\n\nSee [Pagination](/api-reference/introduction/pagination/).\n',
  operationId: 'ListTriggerCategories',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          page: z
            .object({
              after: z.string().exactOptional(),
              before: z.string().exactOptional(),
              size: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'page',
                in: 'query',
                description: 'Pagination parameters',
                style: 'deepObject',
                explode: true,
                schema: {
                  type: 'object',
                  properties: {
                    after: { type: 'string' },
                    before: { type: 'string' },
                    size: { type: 'integer' },
                  },
                },
                example: {
                  after: 'eyJvIjoiLXNjb3JlLGlkIiwidiI6ImFRSUFBQUFBQUFBQWFRMHBJUUVBQUFBQSJ9',
                  before: 'eyJvIjoiLXNjb3JlLGlkIiwidiI6ImFRSUFBQUFBQUFBQWFRMHBJUUVBQUFBQSJ9',
                  size: 50,
                },
                required: false,
              },
              required: [],
            }),
          sort: z
            .enum([
              'position',
              '-position',
              'name',
              '-name',
              'created_at',
              '-created_at',
              'updated_at',
              '-updated_at',
            ])
            .exactOptional()
            .openapi({
              param: {
                name: 'sort',
                in: 'query',
                description: 'Sort parameters',
                schema: {
                  type: 'string',
                  enum: [
                    'position',
                    '-position',
                    'name',
                    '-name',
                    'created_at',
                    '-created_at',
                    'updated_at',
                    '-updated_at',
                  ],
                },
                required: false,
              },
            }),
          include: z
            .literal('rule_counts')
            .exactOptional()
            .openapi({
              param: {
                name: 'include',
                in: 'query',
                description: 'Allowed sideloads',
                schema: { type: 'string', enum: ['rule_counts'] },
                required: false,
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'A paged array of ticket trigger categories',
      content: {
        'application/json': {
          schema: TriggerCategoriesResponseSchema.and(PaginationSchema),
          example: {
            links: {
              next: 'https://{subdomain}.zendesk.com/api/v2/trigger_categories?include=rule_counts&page[after]=eyJvIjoiLXNjb3JlLGlkIiwidiI6ImFRSUFBQUFBQUFBQWFRMHBJUUVBQUFBQSJ9&page[size]=2&sort=position',
              prev: 'https://{subdomain}.zendesk.com/api/v2/trigger_categories?include=rule_counts&page[before]=eyJvIjoiLXNjb3JlLGlkIiwidiI6ImFRSUFBQUFBQUFBQWFRMHBJUUVBQUFBQSJ9&page[size]=2&sort=position',
            },
            meta: {
              after_cursor: 'eyJvIjoiLXNjb3JlLGlkIiwidiI6ImFRSUFBQUFBQUFBQWFRMHBJUUVBQUFBQSJ9',
              before_cursor: 'eyJvIjoiLXNjb3JlLGlkIiwidiI6ImFRSUFBQUFBQUFBQWFRMHBJUUVBQUFBQSJ9',
              has_more: true,
            },
            trigger_categories: [
              {
                created_at: '2020-07-17T01:30:07Z',
                id: '10001',
                name: 'Email Triggers',
                position: 0,
                updated_at: '2020-07-17T01:30:07Z',
              },
              {
                created_at: '2020-07-17T01:30:07Z',
                id: '10002',
                name: 'SMS Triggers',
                position: 1,
                updated_at: '2020-07-17T01:30:07Z',
              },
            ],
          },
        },
      },
    },
    400: {
      description: 'Error',
      content: {
        'application/json': {
          schema: ErrorsSchema,
          example: {
            errors: [{ code: 'InvalidPaginationParameter', title: 'page[after] is not valid' }],
          },
        },
      },
    },
    403: {
      description: 'Error',
      content: {
        'application/json': {
          schema: ErrorsSchema,
          example: {
            errors: [
              {
                code: 'TriggerCategoriesNotEnabled',
                title: 'Ticket trigger categories are not enabled for your account',
              },
            ],
          },
        },
      },
    },
  },
})

