export const getApiV2UsersRoute = createRoute({
  method: 'get',
  path: '/api/v2/users',
  tags: ['Users'],
  summary: 'List Users',
  description:
    '#### Pagination\n\n* Cursor pagination (recommended)\n* Offset pagination\n\nSee [Pagination](/api-reference/introduction/pagination/).\n\nReturns a maximum of 100 records per page.\n\n#### Allowed For\n\n* Admins, Agents and Light Agents\n',
  operationId: 'ListUsers',
  request: {
    query: z.object({
      role: UserRoleFilterParamsSchema,
      'role[]': UserRolesFilterParamsSchema,
      permission_set: UserPermissionSetFilterParamsSchema,
      external_id: UserExternalIdFilterParamsSchema,
      include: UsersIncludeParamsSchema,
      page: DualPaginationPageParamsSchema,
      per_page: PerPageParamsSchema,
      sort: CursorPaginationSortParamsSchema,
      include_boundary_indicators: IncludeBoundaryIndicatorsParamsSchema,
      include_item_cursors: IncludeItemCursorsParamsSchema,
      brand_id: ((schema) =>
        z.union([
          z.preprocess((val) => {
            if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
              return val
            if (/^-?\d+$/.test(val)) return BigInt(val)
            const num = Number(val)
            return Number.isSafeInteger(num) ? BigInt(num) : val
          }, schema),
          schema,
        ]))(
        z.xor([
          z.literal('all'),
          z
            .preprocess(
              (val) =>
                typeof val === 'number' && Number.isSafeInteger(val)
                  ? BigInt(val)
                  : typeof val === 'string' && /^-?\d+$/.test(val)
                    ? BigInt(val)
                    : val,
              z.int64(),
            )
            .openapi({ type: 'integer', format: 'int64' }),
        ]),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'brand_id',
            in: 'query',
            description:
              'When brand separation is enabled, scopes the listing to users belonging to\nthe specified brand. Only applicable when the account has brand separation enabled.\n\nAccepted values:\n\n* "all" — return all users across all brands (no brand filtering applied).\n* 0 — return only account-scoped (brand-less) end users plus all agents and admins.\n* A numeric brand id — if the brand has user separation enabled, return\n  end users belonging to that brand plus the agents with membership in\n  that brand and all admins. If the brand does not have user separation\n  enabled, the request falls back to account scope (0).\n\nIf `brand_id` is omitted, the account\'s `brand_user_separation_scope_query_default`\n[brand setting](/api-reference/ticketing/account-configuration/account_settings/#brands)\ndecides the scope. If it\'s set to `"error"`, the request is rejected with `400 Bad Request`.\nAgent Workspace, other signed-in Zendesk sessions and internal Zendesk requests always use `all`. The resolved\nscope is returned in the `X-Zendesk-Brand-Id-Scope-Resolved` response header.\n',
            schema: {
              oneOf: [
                { type: 'string', enum: ['all'] },
                { type: 'integer', format: 'int64' },
              ],
            },
            example: 'all',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: UsersResponseSchema,
          examples: {
            brand_separated: {
              value: {
                users: [
                  {
                    id: 223443,
                    name: 'Johnny Agent',
                    separation: { brand_id: 123, scope: 'brand' },
                  },
                  {
                    id: 8678530,
                    name: 'James A. Rosen',
                    separation: { brand_id: 123, scope: 'brand' },
                  },
                ],
              },
            },
            default: {
              value: {
                users: [
                  { id: 223443, name: 'Johnny Agent' },
                  { id: 8678530, name: 'James A. Rosen' },
                ],
              },
            },
          },
        },
      },
    },
  },
})

