export const putApiV2UsersUserIdPasswordRoute = createRoute({
  method: 'put',
  path: '/api/v2/users/{user_id}/password',
  tags: ['User Passwords'],
  summary: 'Change Your Password',
  description:
    "You can only change your own password. Nobody can change the password of another user because it requires knowing the user's existing password. However, an admin can set a new password for another user without knowing the existing password. See [Set a User's Password](#set-a-users-password) above.\n\n#### Allowed For\n\n* Agents\n* End Users\n",
  operationId: 'ChangeOwnPassword',
  request: {
    params: z.object({ user_id: UserIdParamsSchema }),
    query: z.object({
      brand_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'brand_id',
            in: 'query',
            description:
              'Sets the active brand context for the password change. Used to scope the session\nto the correct brand when the account has multiple active brands.\n',
            schema: { type: 'integer', format: 'int64' },
            example: 123,
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success description',
      content: {
        'application/json': {
          schema: z.string().openapi({ description: 'Empty response', example: '' }),
          example: '',
        },
      },
    },
  },
})

