export const putApiV2UsersUserIdSuspensionRoute = createRoute({
  method: 'put',
  path: '/api/v2/users/{user_id}/suspension',
  tags: ['Users'],
  summary: "Update a User's Suspension",
  description:
    'Updates the suspension details for a user. `suspended_channels` can be updated when [the messaging channel suspension feature](https://support.zendesk.com/hc/en-us/articles/10575252020250-Announcing-user-suspension-from-messaging-channels-only) is enabled on the account.\n\n#### Allowed For\n\n* Admins\n* [Agents in custom roles with permission](https://support.zendesk.com/hc/en-us/articles/4408882153882#topic_cxn_hig_bd) to manage end users or team members\n\n#### OAuth Scopes\n\nRequires one of the following OAuth scopes: `users:write` or `write`\n',
  operationId: 'UpdateUserSuspension',
  request: {
    params: z.object({ user_id: UserIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: SuspensionUpdateRequestSchema,
          examples: { default: SuspensionUpdateRequestExampleExample },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: SuspensionResponseSchema,
          examples: { default: SuspensionResponseExampleExample },
        },
      },
    },
    400: {
      description:
        "The target user is the current user or the account owner, or `suspended_channels` was supplied but isn't supported on this account",
      content: {
        'application/json': {
          schema: z
            .object({ description: z.string().exactOptional(), error: z.string().exactOptional() })
            .openapi({ required: [] }),
          examples: {
            default: {
              summary: 'Trying to suspend the current user or the account owner',
              value: {
                description: 'You cannot create or modify own suspension',
                error: 'ActionNotAllowed',
              },
            },
            invalid_parameter: {
              summary:
                "suspended_channels was supplied but the account doesn't support channel-specific suspension",
              value: {
                description: 'The suspended_channels parameter is not supported',
                error: 'InvalidParameter',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'User not found, or user is not suspended',
      content: {
        'application/json': {
          schema: z
            .object({ description: z.string().exactOptional(), error: z.string().exactOptional() })
            .openapi({ required: [] }),
          example: { description: 'Not found', error: 'RecordNotFound' },
        },
      },
    },
    422: {
      description:
        "`suspended_channels` contains an invalid combination (channel-specific suspension is only supported for end users, and `all` can't be combined with other channels)",
      content: {
        'application/json': {
          schema: z
            .object({ description: z.string().exactOptional(), error: z.string().exactOptional() })
            .openapi({ required: [] }),
          example: { description: 'Record validation errors', error: 'RecordInvalid' },
        },
      },
    },
  },
})

