export const getApiV2ViewsViewIdTicketsRoute = createRoute({
  method: 'get',
  path: '/api/v2/views/{view_id}/tickets',
  tags: ['Views'],
  summary: 'List Tickets From a View',
  description:
    '#### Allowed For\n\n* Agents\n\n#### Pagination\n* Cursor pagination (recommended)\n* Offset pagination\n\nSee [Pagination](/api-reference/introduction/pagination/).\n',
  operationId: 'ListTicketsFromView',
  request: {
    params: z.object({
      view_id: ((schema) =>
        z.union([
          z.preprocess((val) => {
            if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
              return val
            if (/^-?\d+$/.test(val)) return BigInt(val)
            const num = Number(val)
            return Number.isSafeInteger(num) ? BigInt(num) : val
          }, schema),
          schema,
        ]))(
        z.xor([
          z
            .preprocess(
              (val) =>
                typeof val === 'number' && Number.isSafeInteger(val)
                  ? BigInt(val)
                  : typeof val === 'string' && /^-?\d+$/.test(val)
                    ? BigInt(val)
                    : val,
              z.int64(),
            )
            .openapi({ type: 'integer', format: 'int64' }),
          z.enum(['incoming', 'my', 'my_groups']),
        ]),
      ).openapi({
        param: {
          name: 'view_id',
          in: 'path',
          description:
            'The ID of the view, or one of the string aliases `"incoming"`, `"my"`, or `"my_groups"`.',
          required: true,
          schema: {
            oneOf: [
              { type: 'integer', format: 'int64' },
              { type: 'string', enum: ['incoming', 'my', 'my_groups'] },
            ],
          },
          example: 25,
        },
      }),
    }),
    query: z.object({
      sort_by: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sort_by',
            in: 'query',
            description:
              'Sort or group the tickets by a column in the [View columns](#view-columns) table. The `subject` and `submitter` columns are not supported',
            schema: { type: 'string' },
            required: false,
          },
        }),
      sort_order: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sort_order',
            in: 'query',
            description:
              'One of "asc" or "desc". Defaults to "asc" for alphabetical and position sort, "desc" for all others',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: TicketsResponseSchema,
          examples: { default: ViewListTicketsResponseEXampleExample },
        },
      },
    },
  },
})

