export const getApiV2ViewsCountManyRoute = createRoute({
  method: 'get',
  path: '/api/v2/views/count_many',
  tags: ['Views'],
  summary: 'Count Tickets in Views',
  description:
    "Returns the ticket count of each view in a list of views. Accepts up to 20 view ids per request. For the ticket count of a single view, see [Count Tickets in View](#count-tickets-in-view).\n\nOnly returns values for personal and shared views accessible to the user performing the request.\n\n***Note:***\nDue to the asynchronous operation of computing the counts for the requested views, some of the views' counts could be null. This means that the system is still computing the count for that view.\nPeriodically issue another request until all of the views' counts in the response are integers greater than zero. \n\n#### Rate limiting\n\nThis endpoint is rate limited to 6 requests every 1 minute.\n\n#### Allowed For\n\n* Agents\n",
  operationId: 'GetViewCounts',
  request: {
    query: z.object({
      ids: z
        .string()
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            description: "List of view's ids separated by commas.",
            required: true,
            schema: { type: 'string' },
            example: '1,2,3',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response',
      content: {
        'application/json': {
          schema: ViewCountsResponseSchema,
          examples: { default: ViewCountsResponseExampleExample },
        },
      },
    },
    429: {
      description: 'Too Many Requests',
      content: {
        'application/json': {
          schema: ErrorsSchema,
          examples: {
            default: {
              value: {
                errors: [{ code: 'TooManyRequests', title: 'Too many requests to update' }],
              },
            },
          },
        },
      },
    },
  },
})

