export const deleteApiV2WorkspacesDestroyManyRoute = createRoute({
  method: 'delete',
  path: '/api/v2/workspaces/destroy_many',
  tags: ['Workspaces'],
  summary: 'Bulk Delete Workspaces',
  description: '#### Allowed For\n* Admins\n',
  operationId: 'DestroyManyWorkspaces',
  request: {
    query: z.object({
      ids: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z
              .preprocess((val) => {
                if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                  return val
                if (/^-?\d+$/.test(val)) return BigInt(val)
                const num = Number(val)
                return Number.isSafeInteger(num) ? BigInt(num) : val
              }, z.int64())
              .openapi({ type: 'integer', format: 'int64' }),
          ),
        )
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            description: 'The ids of the workspaces to delete',
            required: true,
            schema: { type: 'array', items: { type: 'integer', format: 'int64' } },
            example: [1, 2, 3],
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Succesful response',
      content: {
        'application/json': {
          schema: z.string().openapi({ description: 'Empty response', example: '' }),
          example: '',
        },
      },
    },
  },
})

